(window.GIM_TS=window.GIM_TS||{})["Avodah Zarah.5"]={"from":120,"a":[["הגוי \u0003השוכר את הפועל\u0004 הישראל על מנת \u0003לעשות עמו\u0004 (אצלו) מלאכה \u0003ביין נסך\u0004 — \u0003שכרו אסור.\u0004 אם \u0003שכרו לעשות עמו מלאכה אחרת, אף על פי שאמר לו\u0004 בתוך זמן עבודתו: \u0003\"העבר לי חבית של יין נסך ממקום למקום\"\u0004 — \u0003שכרו מותר. השוכר את החמור\u0004 על מנת \u0003להביא עליה יין נסך\u0004 — \u0003שכרה אסור. שכרה לישב עליה, אף על פי שהניח גוי לגינו\u0004 (כדו) \u0003עליה\u0004 ובו יין נסך — בכל זאת \u0003שכרה מותר.\u0004","ומבררים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003שכרו\u0004 של הפועל העושה ביין נסך \u0003אסור? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003הואיל ויין נסך אסור בהנאה, שכרו נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור,\u0004 על כך יש להקשות: \u0003הרי ערלה וכלאי הכרם\u0004 שאף הם \u0003אסורין בהנאה, ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 למרות שאסור לו למוכרם, אם \u0003מכרן וקידש\u0004 אשה \u0003בדמיהן\u0004 שקיבל — \u0003מקודשת,\u0004 ואין אנו אומרים שהכסף שקיבל אף הוא אסור בהנאה ולא תהא מקודשת!","\u0003אלא\u0004 תאמר כי טעם הדבר הוא — \u0003הואיל ותופס את דמיו כעבודה זרה,\u0004 שכשם שהמוכר עבודה זרה דמיו אסורים, כך שכר שמקבל בשל עבודה ביין הנסך נחשב כיין נסך. אולם גם על כך יש להקשות: \u0003והרי שביעית\u0004 שגם היא \u0003תופסת את דמיה,\u0004 שכל דבר שקונה בפירות שביעית יש לו קדושת שביעית, \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003האומר לפועל\u0004 בשנת השביעית: \u0003\"הילך דינר זה, לקוט לי בו\u0004 בשוויו \u0003ירק היום\"\u0004 — \u0003שכרו אסור\u0004 כלומר, יש בשכר זה קדושת שביעית, שהרי הוא כקונה פירות שביעית בדינר זה. אבל אם אמר לו סתם: \u0003\"לקוט לי ירק היום\"\u0004 — \u0003שכרו מותר\u0004 לפי שהוא שילם רק שכר עבודתו. ומדוע שונה דין עבודה זרה?","על כך מביאים מה ש\u0003אמר ר' אבהו אמר ר' יוחנן: קנס הוא שקנסו חכמים ב\u0004שכר \u0003חמרין\u0004 (מובילי חמורים) \u0003וביין נסך\u0004 שבשני מקרים אלה אין הדבר אסור מעיקר הדין, אלא שקנסו בהם חכמים. ומסבירים, \u0003יין נסך\u0004 — \u0003הא דאמרן\u0004 \u0005[זה שאמרנו]\u0006 שמי שמקבל שכר עבור עבודה ביין נסך — שכרו נאסר. \u0003חמרין מאי היא\u0004 \u0005[מה הוא]?\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003החמרין שהיו עושין מלאכה בפירות שביעית\u0004 — \u0003שכרן שביעית.\u0004","ומביאים דיון בענין זה: \u0003מאי\u0004 \u0005[מהו\u0006 פירוש\u0005]\u0006 \u0003\"שכרן שביעית\"? אילימא דיהבינן להו\u0004 \u0005[אם תאמר שנותנים להם]\u0006 את ה\u0003שכר\u0004 עבור מלאכתם זו \u0003מפירות שביעית, נמצא זה\u0004 שלקחם לעבודה \u0003פורע חובו מפירות שביעית\u0004 ונהנה מהפירות הללו באופן מסחרי, \u0003והתורה אמרה:\u0004 \"והיתה שבת הארץ לכם \u0003לאכלה\"\u0004 (ויקרא כה, ו) \u0003ולא לסחורה!\u0004","\u0003ואלא\u0004 תאמר ששכרן שביעית משמעו ש\u0003קדוש שכרן בקדושת שביעית,\u0004 שיש דין קדושת שביעית על השכר שהם מקבלים. \u0003ומי\u0004 \u0005[והאם]\u0006 שכר זה נעשה \u0003קדוש? והתניא\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003האומר לפועל: \"הילך דינר זה ולקוט לי ירק היום\"\u0004 — \u0003שכרו מותר,\u0004 אבל אם אמר לו: \u0003\"לקוט לי ירק בו היום\"\u0004 — \u0003שכרו אסור.\u0004 משמע שמי שקיבל שכר עבור פירות שביעית, שכרו אינו מתקדש בקדושת שביעית!","\u0003אמר אביי: לעולם\u0004 תפרש ש\u0003יהבינן ליה\u0004 \u0005[נותנים לו]\u0006 \u0003שכר מפירות שביעית, ודקא קשיא לך\u0004 \u0005[ו\u0006מה \u0005שהיה קשה לך]:\u0006 הלוא אנו למדים שפירות שביעית ניתנו \u0003לאכלה ולא לסחורה!\u0004 יש להסביר \u0003דיהביה ניהליה\u0004 \u0005[שנותן לו\u0006 את הפירות\u0005]\u0006 \u0003בצד היתר,\u0004 כלומר בדרך מתנה, ולא כתשלום שכר. \u0003כדתנן\u0004 \u0005[כמו ששנינו\u0006 במשנה\u0005]\u0006 לענין מעשר שני, \u0003לא יאמר אדם לחבירו:\u0004"],["\u0003\"העלה לי פירות הללו\u0004 של מעשר שני \u0003לירושלים לחלק\"\u0004 כלומר, כדי שתיטול אתה בהם חלק בירושלים, לפי שבכך הריהו כעושה מסחר בפירות מעשר, שנותן לו שכר. \u0003אבל אומר לו: \"העלם לאוכלם ולשתותם בירושלים\"\u0004 בלי לפרש שיתן לו על כך שכר, \u0003ו\u0004שם בירושלים \u0003נותנין זה לזה מתנה של חנם.\u0004 ומכאן נלמד שדברים שאסור לתת אותם כשכר, מכל מקום אם נותן אותם בדרך מתנה — הרי זה מותר, ואם כן אפשר לשלם לחמרים שכרם מפירות שביעית.","\u0003ורבא אמר: לעולם\u0004 תפרש ש\u0003קדוש\u0004 שכרם \u0003בקדושת שביעית, ודקא קשיא לך\u0004 \u0005[ו\u0006מה \u0005שהיה קשה לך]\u0006 בענין \u0003פועל\u0004 שנאמר בברייתא שאין שכרו קדוש בקדושת שביעית — יש להבחין: \u0003פועל דלא נפיש אגריה\u0004 \u0005[שאין שכרו מרובה]\u0006 — \u0003לא קנסוהו רבנן\u0004 \u0005[חכמים]\u0006 שיהא שכרו מתקדש בקדושת שביעית, \u0003חמרין דנפיש אגרייהו\u0004 \u0005[שמרובה שכרם]\u0006 — \u0003קנסו רבנן בהו\u0004 \u0005[חכמים בהם].\u0006 \u0003ומתניתין\u0004 \u0005[ומשנתנו]\u0006 בענין יין נסך, שאפילו פועל נאסר שכרו, יש לומר כי \u0003חומרא\u0004 של \u0003יין נסך שאני\u0004 \u0005[שונה]\u0006 ומחמירים בה יותר מפירות שביעית.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: אם הגוי \u0003שכרו\u0004 לפועל היהודי, לא ליין נסך כבמשנתנו, אלא \u0003ל\u0004עשות ב\u0003סתם יינן\u0004 של גוים, \u0003מהו\u0004 הדין? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003כיון דאיסורא\u0004 \u0005[שהאיסור\u0006 שבזה\u0005]\u0006 \u0003חמור\u0004 כמו של \u0003יין נסך,\u0004 שאסרוהו בהנאה — \u0003שכרו נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור, או דלמא\u0004 \u0005[שמא]\u0006 \u0003הואיל וטומאתו קיל\u0004 \u0005[קלה],\u0006 שאין לו דין טומאת יין נסך, \u0003אף שכרו נמי קיל\u0004 \u0005[גם כן\u0006 דינו \u0005קל\u0006 יותר\u0005]?\u0006","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לדבר: \u0003דההוא גברא דאגר ארביה\u0004 \u0005[שאדם אחד השכיר\u0006 את \u0005אונייתו]\u0006 \u0003ל\u0004הוביל בה \u0003סתם יינן, יהבו ליה חיטי באגרא\u0004 \u0005[נתנו לו חיטים בשכרו],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב חסדא\u0004 לשאול מה דינן של החיטים, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל קלינהו וקברינהו בקברי\u0004 \u0005[לך שרוף אותם וקבור אותם ב\u0006בית ה\u0005קברות].\u0006 הרי שנפסקה הלכה ששכר סתם יינם אף הוא אסור בהנאה.","אלא שלעצם דברי רב חסדא שואלים: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]:\u0006 \u0003בדרינהו\u0004 \u0005[פזר אותם]!\u0006 ולמה צריך לשורפם? ומשיבים: \u0003אתו בהו\u0004 \u0005[\u0006שמא \u0005יבואו בהם]\u0006 אנשים \u0003לידי תקלה,\u0004 שהמוצאים יאכלו אותם. ומקשים: \u0003וליקלינהו וליבדרינהו\u0004 \u0005[ושישרוף אותן ושיפזר אותן],\u0006 ומדוע צריך לקוברן? ומשיבים: \u0003דלמא מזבלי בהו\u0004 \u0005[שמא יזבלו בהן]\u0006 בחיטים שנשרפו את השדות. ושואלים עוד: לשם מה לשורפן?","\u0003ולקברינהו בעינייהו\u0004 \u0005[ושיקבור אותן בעינן,\u0006 כמות שהן\u0005]!\u0006 \u0003מי לא תנן\u0004 \u0005[האם לא שנינו]\u0006 כיוצא בו לגבי הרוגי בית דין ש\u0003אחד אבן שנסקל בה\u0004 החייב סקילה, \u0003ואחד עץ שנתלה עליו, ואחד סייף שנהרג בו, ואחד סודר שנחנק בו\u0004 — \u0003כולם נקברים עמו,\u0004 שכולם אסורים בהנאה כמת עצמו. אבל לא נאמר שצריך לשרפם ואחר כך לקוברם!","ומשיבים: \u0003התם דקא קברי בבי דינא\u0004 \u0005[שם, שקוברים\u0006 את ההרוגים \u0005בבית הדין],\u0006 ויחד עימם חפצים אלו, \u0003מוכחא מילתא\u0004 \u0005[מוכח הדבר]\u0006 ש\u0003הרוגי בית דין נינהו\u0004 \u0005[הם],\u0006 והכל יודעים שאין משתמשים באלה. \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003לא מוכחא מילתא\u0004 \u0005[מוכח הדבר]\u0006 שנקברו החיטים משום איסור, \u0003אימר: אינש גנב ואייתי קברא הכא\u0004 \u0005[אמור: אדם גנב\u0006 את החיטים \u0005והביא וקבר\u0006 אותם \u0005כאן],\u0006 ויבואו להשתמש בהן.","מסופר, \u0003דבי\u0004 \u0005[\u0006בני \u0005ביתו\u0006 של\u0005]\u0006 \u0003ר' ינאי יזפי פירי\u0004 \u0005[היו לווים פירות]\u0006 \u0003שביעית מעניים, ופרעו להו\u0004 \u0005[ו\u0006היו \u0005פורעים להם]\u0006 עבור הפירות הללו \u0003בשמינית, אתו\u0004 \u0005[באו]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לר' יוחנן\u0004 בתמיהה ותלונה על מה שהם עושים, שחליפי שביעית הם. \u0003אמר להו\u0004 \u0005[להם]\u0006 ר' יוחנן: \u0003יאות הן עבדין\u0004 \u0005[יפה הם עושים],\u0006 שאין זה נקרא חליפי שביעית.","\u0003וכנגדן\u0004 במקרה כיוצא בזה \u0003ב\u0004דין \u0003אתנן\u0004 שאסור בהקרבה למזבח — גם הוא \u0003מותר, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003נתן לה\u0004 לזונה אתנן \u0003ולא בא עליה,\u0004 או \u0003בא עליה ולא נתן לה\u0004 — \u0003אתננה מותר.\u0004","ותחילה יש לברר ענינה של הברייתא, כי לשונה תמוהה: \u0003נתן לה ולא בא עליה\u0004 — \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שהוא מותר, שהרי \u0003כיון\u0004 ש\u0003לא בא עליה, מתנה בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא דיהיב\u0004 \u0005[שנתן]\u0006 \u0003לה\u0004 ומדוע ייאסר? \u0003ותו\u0004 \u0005[ועוד]\u0006 יש לשאול: \u0003בא עליה ולא נתן לה\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא יהיב\u0004 \u0005[נתן]\u0006 \u0003לה ולא מידי\u0004 \u0005[דבר],\u0006 \u0003וכיון\u0004 ש\u0003לא נתן לה מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אתננה מותר\"?\u0004","\u0003אלא הכי קאמר\u0004 \u0005[הוא אומר]\u0006 כך יש לפרש את הברייתא: \u0003נתן לה\u0004 תחילה מתנה \u0003ואחר כך\u0004 לאחר זמן \u0003בא עליה, או בא עליה ואחר כך\u0004 לאחר זמן \u0003נתן לה\u0004 — בשני המקרים הללו \u0003אתננה מותר,\u0004 לפי שלא היה אתנן קיים בשעת הביאה. וכן הוא הדין בלווה פירות שביעית, שדמיהם שלאחר זמן אינם חליפי שביעית.","ושואלים: אם \u0003נתן לה ואחר כך בא עליה, לכי\u0004 \u0005[כאשר]\u0006 הוא \u0003בא עליה\u0004"],["\u0003ליחול עלה\u0004 \u0005[שיחול עליה]\u0006 על המתנה הזו \u0003איסור אתנן למפרע,\u0004 שהרי מתברר למפרע שאתנן נתן! \u0003אמר ר' אליעזר:\u0004 מדובר \u0003כשקדמה והקריבתו\u0004 למזבח לפני שבא עליה, ואין מה שיחול עליו האיסור למפרע.","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003אמר לה\u0004 כשנתנו לה: \u0003\"קני ליך\u0004 \u0005[לך]\u0006 את האתנן \u0003מעכשיו\"\u0004 — \u0003פשיטא דשרי\u0004 \u0005[פשוט\u0006 הוא \u0005שמותר],\u0006 \u0003דהא ליתיה\u0004 \u0005[שהרי אינו\u0006 קיים\u0005]\u0006 \u0003בשעת ביאה, ומתנה בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא דיהיב\u0004 \u0005[שנתן]\u0006 \u0003לה!\u0004","\u0003ואי\u0004 \u0005[ואם]\u0006 ש\u0003לא אמר לה \"קני ליך מעכשיו\", היכי מצי מקרבה\u0004 \u0005[כיצד יכולה\u0006 היתה \u0005להקריב]\u0006 אותו קודם? הלוא \u0003\"ואיש כי יקדש את ביתו קדש\u0004 לה'\" (ויקרא כז, יד) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ולמדים מכאן: \u0003מה ביתו ברשותו, אף כל\u0004 דבר שאדם מקדיש צריך להיות \u0003ברשותו,\u0004 ואין אדם יכול להקדיש דבר שאינו שלו!","\u0003אלא\u0004 מדובר ש\u0003אמר לה: \"להוי גביך\u0004 \u0005[שיהיה\u0006 האתנן \u0005אצלך]\u0006 \u0003עד שעת ביאה, ואי מיצטריך ליך\u0004 \u0005[ואם יצטרך לך]\u0006 \u0003קני\u0004 אותו \u0003מעכשיו\",\u0004 ובכגון זה חידשה הברייתא שהוא מותר.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב הושעיא: קדמה\u0004 הזונה \u0003והקדישתו\u0004 את האתנן קודם הביאה, אף שלא הקריבתו עדיין, \u0003מהו,\u0004 מה דינו? וצדדי השאלה: \u0003כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אמירתו לגבוה כמסירתו להדיוט\u0004 שכל דבר שמקדישים בדיבור בלבד לשם שמים, הרי דינו לענין קניינים כמו מסירה שמוסרים חפץ להדיוט, אם כן, כיון שהקדישתו בדיבור \u0003כמאן דאקריבתיה דמי\u0004 \u0005[כמי שהקריבה אותו\u0006 הוא \u0005נחשב],\u0006 ואינו קרוי אתנן. \u0003או דלמא השתא מיהא הא קאי ואיתיה בעיניה\u0004 \u0005[שמא עכשיו על כל פנים הרי הוא עומד וישנו בעינו]\u0006 ולכן חל עליו האיסור?","ושואלים: \u0003ותפשוט\u0004 \u0005[ותפתור]\u0006 בעיה זו \u0003מ\u0004דברי \u0003ר' אליעזר,\u0004 ש\u0003אמר ר' אליעזר\u0004 שמדובר ב\u0003שקדמה והקריבתו,\u0004 ונדייק מכאן: \u0003דוקא הקריבתו, אבל הקדישתו\u0004 — \u0003לא!\u0004","ודוחים: מה שאמר \u0003ר' אליעזר גופיה\u0004 \u0005[עצמו]\u0006 \u0003קא מיבעיא ליה\u0004 \u0005[היה מסופק לו]\u0006 לרב הושעיא \u0003מאי\u0004 \u0005[מה]\u0006 היתה כוונתו? \u0003מיפשט פשיטא ליה\u0004 \u0005[\u0006האם \u0005פשוט לו\u0006 הדבר\u0005]\u0006 \u0003לר' אליעזר\u0004 ש\u0003הקריבתו דוקא, אבל הקדישתו\u0004 — \u0003לא,\u0004 והאתנן אסור, \u0003דהא איתיה\u0004 \u0005[שהרי ישנו]\u0006 \u0003בשעת ביאה, או דלמא\u0004 \u0005[שמא]\u0006 \u0003הקריבתו פשיטא ליה\u0004 \u0005[פשוט לו],\u0006 \u0003והקדישתו מספקא ליה\u0004 \u0005[מסופק לו],\u0006 ולכן לא נקט בדוגמה זו, אבל לא הכריע בדבר. שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","נאמר בברייתא לעיל שאם \u0003בא עליה ואחר כך נתן לה\u0004 — \u0003אתננה מותר. ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005],\u0006 ששנינו בברייתא אחרת: \u0003בא עליה ואחר כך נתן לה, אפילו מכאן עד שלש שנים\u0004 — \u0003אתננה אסור!\u0004","\u0003אמר רב נחמן בר יצחק אמר רב חסדא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003אמר\u0004 מראש: \u0003\"התבעלי לי בטלה זה\",\u0004 ואז טלה זה נחשב מיד כשלה, אפילו נמסר לה רק לאחר זמן. \u0003הא\u0004 \u0005[זה ]\u0006 ש\u0003אמר\u0004 \u0003לה:\u0004 \u0003\"התבעלי בטלה\" סתם,\u0004 שלא ייחד לה טלה מסויים בשעת הביאה, ולכן כשנתן לה לאחר ביאה — שוב אין זה נחשב אתנן.","ושואלים: \u0003וכי אמר\u0004 \u0005[וכאשר אומר]\u0006 \u0003לה \"בטלה זה\" מאי הוי\u0004 \u0005[מה בכך]?\u0006 \u0003הא מחסר\u0004 \u0005[הרי\u0006 הוא \u0005מחוסר]\u0006 \u0003משיכה,\u0004 שלא משכה אותו, ונמצא שלא קנתה אותו עדיין! ומשיבים: מדובר שם \u0003בזונה גויה, דלא קניא\u0004 \u0005[שאינה קונה]\u0006 \u0003במשיכה,\u0004 אלא בכסף. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם\u0004 מדובר \u0003בזונה ישראלית, וכגון דקאי\u0004 \u0005[שהיה]\u0006 הטלה עומד כבר \u0003בחצירה,\u0004 וקנתה אותו מדין קנין חצר, שאדם קונה לו מה שברשותו.","ושואלים: \u0003אי דקאי\u0004 \u0005[אם\u0006 מדובר \u0005ש\u0006הוא \u0005עומד]\u0006 \u0003בחצירה,\u0004 אין זה מקרה ש\u0003בא עליה ואחר כך נתן לה, הא קניא לה\u0004 \u0005[הרי\u0006 הוא כבר \u0005קנוי לה],\u0006 מזמן שהיה בחצר, קודם שבא עליה! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא במקרה \u0003דשויה ניהלה אפותיקי\u0004 \u0005[שעשה את הטלה עבורה כמשכון],\u0006 ש\u0003אמר לה: \"אי מייתינא ליך זוזי\u0004 \u0005[אם אביא לך כסף]\u0006 \u0003מכאן עד יום פלוני\u0004 — \u0003מוטב\u0004 ותחזירי לי את הטלה, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 אביא כסף — \u0003שקליה\u0004 \u0005[קחי אותו]\u0006 \u0003באתנניך\".\u0004","ושבים לדון במה שנהגו בית ר' ינאי ללוות מעניים בשביעית ולפרוע בשמינית, ועל כך אמר ר' יוחנן שאין זה קרוי חליפי שביעית. \u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רב ששת: אומר אדם לחמריו ולפועליו\u0004 שהם גוים או עמי הארץ, שנותן להם כסף ואומר: \u0003\"לכו ואכלו בדינר זה\",\u0004 או אומר \u0003\"צאו ושתו בדינר זה\", ואינו חושש\u0004"],["\u0003לא משום שביעית ולא משום מעשר ולא משום יין נסך\u0004 שאם קנו הפועלים דברים אלה שיש בהם איסור, הרי הם קונים משלהם ועל דעת עצמם.","\u0003ו\u0004אולם \u0003אם אמר להם: \"צאו ואכלו ואני פורע\", \"צאו ושתו ואני פורע\"\u0004 — \u0003חושש\u0004 כלומר, אסור הדבר, שעליו לחשוש \u0003משום שביעית, משום מעשר ומשום יין נסך,\u0004 שהרי זה כאילו קונה דבר אסור ונותן להם משלו.","ונלמד מכאן: \u0003אלמא\u0004 \u0005[מכאן]\u0006 \u0003כי קא פרע\u0004 \u0005[כאשר הוא פורע]\u0006 לאחר זמן, נחשב הדבר ש\u0003דמי איסור קא פרע\u0004 \u0005[הוא פורע]\u0006 למרות שהאיסור שוב אינו קיים, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 באופן שנהגו דבי ר' ינאי, שלוו פירות שביעית כדי לפורעם לאחר זמן, \u0003כי קא פרע\u0004 \u0005[כאשר הוא פורע]\u0006 — \u0003דמי איסורא קא פרע\u0004 \u0005[דמי איסור הוא פורע]!\u0006","\u0003תרגמה\u0004 \u0005[הסביר אותה]\u0006 \u0003רב חסדא\u0004 אותה ברייתא \u0003בחנוני המקיפו\u0004 שהוא רגיל לקחת אצלו בהקפה, שהוא \u0003משתעבד ליה\u0004 \u0005[לו]\u0006 מזמן שנתן אוכל או משקה לפועליו, ש\u0003כיון דאורחיה לאקופי\u0004 \u0005[שדרכו להקיף לו]\u0006 — \u0003קני ליה דינר גביה\u0004 \u0005[קנוי לו\u0006 לחנווני \u0005הדינר אצלו]\u0006 מאותה שעה, ולכן הרי זה כקונה ופורע לפועליו מפירות שביעית ממש.","ושואלים: \u0003אבל חנוני שאין מקיפו מאי\u0004 \u0005[מה]\u0006 יהא הדין, \u0003מותר? אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אדתני\u0004 \u0005[עד ש\u0006הוא \u0005שונה]\u0006 בתחלת הברייתא: \u0003\"צאו ואכלו בדינר זה\", \"צאו ושתו בדינר זה\",\u0004 שהוא מותר, \u0003ליפלוג וליתני בדידה\u0004 \u0005[שיחלק וישנה בה\u0006 עצמה\u0005]\u0006 במקרה שאומר \"צאו ואכלו ואני פורע\", שאסור:","\u0003במה דברים אמורים? בחנוני המקיפו,\u0004 ש\u0003משתעבד ליה\u0004 \u0005[לו],\u0006 \u0003אבל חנוני שאין מקיפו\u0004 — \u0003מותר!\u0004","\u0003ועוד\u0004 יש להקשות: \u0003חנוני שאין מקיפו מי\u0004 \u0005[האם]\u0006 \u0003לא משתעבד\u0004 לו בעל הבית במקרה כזה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא, האומר לחבירו: \"תן מנה לפלוני ויקנו כל נכסאי לך\"\u0004 אף על פי שבעל הנכסים עצמו לא קיבל תמורה, בכל זאת \u0003קנה\u0004 חבירו את הנכסים כאשר נתן את המנה לאותו פלוני, והוא \u0003מדין ערב,\u0004 שכשם שערב (שלא קיבל את ההלוואה) מתחייב בתשלום עבור חובו של אחר, כך בעל הנכסים מתחייב לתת אותם עבור המנה שנתן חבירו לאותו פלוני. ואף כאן משתעבד בעל הבית לחנווני כשהלה נותן אוכל לפועליו במצוותו!","\u0003אלא אמר רבא: לא שנא\u0004 \u0005[אינו שונה]\u0006 אם היה החנווני \u0003מקיפו ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003שאין מקיפו,\u0004 כל התחייבות לשלם גוררת אחריה שיעבוד. ואולם, \u0003אף על גב דמשעבד ליה\u0004 \u0005[אף על פי ש\u0006הוא \u0005משתעבד לו],\u0006 \u0003כיון\u0004 ש\u0003לא מייחד שיעבודיה\u0004 \u0005[מיוחד שיעבודו]\u0006 לשלם לו במעות מסויימים — \u0003לא מיתסר\u0004 \u0005[אינו נאסר],\u0006 כגון במקרה של דבי ר' ינאי.","ושואלים: אם כן, \u0003אלא הכא אמאי\u0004 \u0005[כאן\u0006 בברייתא \u0005מדוע]\u0006 \u0003חושש משום שביעית? הא לא מייחד שיעבודיה הכא\u0004 \u0005[הרי לא מיוחד שיעבודו כאן]!\u0006 \u0003אמר רב פפא: כגון שהקדים לו דינר\u0004 לשלם לחנווני עבור מה שנתן לפועלים, ונמצא כקונה איסור ומשלם להם ממנו שכרם.","\u0003אמר רב כהנא: אמריתה לשמעתא קמיה\u0004 \u0005[אמרתי את השמועה\u0006 הזו \u0005לפני]\u0006 \u0003רב זביד מנהרדעא, אמר לי: אי הכי\u0004 \u0005[אם כך]\u0006 מסבירים, שמדובר כשהקדים לו דינר, \u0003אדתני\u0004 \u0005[עד ש\u0006הוא \u0005שונה\u0006 בברייתא\u0005]\u0006 בלשון \u0003\"צאו ואכלו, צאו ושתו, ואני פורע\",\u0004 הרי אין זו הלשון הראויה, אלא \u0003\"צאו ואכלו, צאו ושתו, ואני מחשב\" מיבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו\u0006 לומר\u0005],\u0006 כלומר, ואני כבר אחשב מה עוד נותר לי לשלם לו! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אין זו קושיה, \u0003תני\u0004 \u0005[שנה]\u0006 ותקן: \u0003\"צאו ואני מחשב\".\u0004","\u0003רב אשי אמר:\u0004 מדובר בברייתא \u0003כגון שנטל ונתן ביד\u0004 שבעל הבית עצמו הוא הלוקח מן החנווני ונותן לפועלים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יימר לרב אשי: אי הכי אדתני\u0004 \u0005[אם כך, עד ש\u0006הוא \u0005שונה\u0006 בברייתא\u0005]\u0006 \u0003\"צאו ואכלו, צאו ושתו\",\u0004 אין זו הלשון הנכונה, אלא \u0003\"טלו ואכלו, טלו ושתו\" מיבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו\u0006 לומר\u0005]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אכן, \u0003תני\u0004 \u0005[שנה כך]:\u0006 \u0003\"טלו ואכלו, טלו ושתו\".\u0004","ושבים לעיקר דין משנתנו שהעושה ביין נסך שכרו אסור. מסופר, \u0003יתיב\u0004 \u0005[יושבים\u0006 היו\u0005]\u0006 \u0003רב נחמן ועולא ואבימי בר פפי ויתיב\u0004 \u0005[\u0006ו\u0005יושב\u0006 היה\u0005]\u0006 \u0003ר' חייא בר אמי גבייהו\u0004 \u0005[לידם],\u0006 שהוא היה כתלמיד להם, \u0003ויתבי וקא מיבעיא להו\u0004 \u0005[והיו יושבים ונסתפקה להם]\u0006 בעיה זו: אם \u0003שכרו\u0004 לפועל \u0003לשבור ביין נסך\u0004 שישבור החביות ויישפך היין, \u0003מהו?\u0004 מה הדין? \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003כיון\u0004 ש\u0003רוצה בקיומו\u0004 — \u0003אסור,\u0004 והרי הפועל רוצה בקיומן של החביות עד שהוא ישבור אותן, כדי לקבל את שכרו, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כל\u0004 דבר שיש בו \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003תיפלה\u0004 (את האיסור) \u0003שפיר דמי\u0004 \u0005[יפה]\u0006 הדבר, גם אם הוא משתכר מעצם השבירה?","\u0003אמר רב נחמן: ישבור ותבא עליו ברכה.\u0004 ומציעים: \u0003לימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 כי \u0003מסייע ליה\u0004 \u0005[לו]\u0006 מה ששנינו בברייתא: \u0003אין עודרין עם הגוי ב\u0004שדה שיש בו \u0003כלאים,\u0004"],["\u0003אבל עוקרין עמו\u0004 את גידולי הכלאים, \u0003כדי למעוטי\u0004 \u0005[למעט]\u0006 \u0003את התיפלה,\u0004 למרות שרצונו בקיומם עד שייעקרו, כדי שיטול שכרו.","ומעירים: \u0003סברוה\u0004 \u0005[חשבו\u0006 חכמים מתחילה\u0005]\u0006 שברייתא \u0003הא\u0004 \u0005[זו]\u0006 כשיטת \u0003מני\u0004 \u0005[מי היא]?\u0006 שיטת \u0003ר' עקיבא היא,\u0004 ש\u0003אמר: המקיים בכלאים\u0004 — \u0003לוקה,\u0004 שלא רק זה שעושה פעולה של זריעה וגידול, אלא גם מי שמאפשר את קיומם — אף הוא לוקה. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003המנכש\u0004 עשבים שוטים המפריעים לצמיחת הגידולים, \u0003והמחפה\u0004 זרעים באדמה, שעושה מעשה כדי לסייע לגידול ה\u0003כלאים\u0004 — \u0003לוקה, ר' עקיבא אומר: אף המקיים\u0004 לוקה.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' עקיבא?\u0004 ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"שדך לא תזרע כלאים\"\u0004 (ויקרא יט, יט), \u0003אין לי אלא זורע\u0004 כלאים, \u0003מקיים מנין\u0004 שגם כן אסור? \u0003תלמוד לומר: \"לא כלאים\"\u0004 כלומר, עשה שבשום אופן שלא יהיו כלאים.","\u0003ואילו למעוטי\u0004 \u0005[למעט]\u0006 \u0003תיפלה שרי\u0004 \u0005[מותר]\u0006 לו לעקור עם הגוי בכלאים, למרות שהוא רוצה בינתיים בקיומם כדי לקבל את שכרו.","ודוחים: \u0003לא, הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא,\u0004 שמתירים לקיים כלאים אבל לענין יין נסך שאסור לקיימו — אין מכאן ראיה.","ושואלים: \u0003אי רבנן\u0004 \u0005[אם\u0006 הברייתא כשיטת \u0005חכמים],\u0006 \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 התירו בברייתא שיהו \u0003עוקרין\u0004 עם הגוי? \u0003אפילו קיומי נמי שפיר דמי\u0004 \u0005[לקיים גם כן מותר]!\u0006 ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון דקא עביד\u0004 \u0005[שהוא עושה]\u0006 את העקירה \u0003בחנם, ו\u0004שיטת \u0003ר' יהודה היא,\u0004 ש\u0003אמר: ליתן להם\u0004 לגוים \u0003מתנת חנם\u0004 — \u0003אסור.\u0004","ואומרים על כך: מכל מקום \u0003מ\u0004דברי \u0003ר' יהודה נשמע לר' עקיבא, לאו\u0004 \u0005[האם לא]\u0006 \u0003אמר ר' יהודה: אסור ליתן להם מתנת חנם, אבל\u0004 בכל זאת \u0003למעוטי תיפלה שפיר דמי\u0004 \u0005[למעט\u0006 את \u0005התיפלה מותר הדבר],\u0006 אף שהוא עושה זאת בחינם. \u0003לר' עקיבא נמי\u0004 \u0005[גם כן],\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003אמר ר' עקיבא: המקיים בכלאים\u0004 — \u0003לוקה, למעוטי\u0004 \u0005[למעט]\u0006 \u0003תיפלה\u0004 \u0003שפיר דמי\u0004 \u0005[מותר הדבר]!\u0006 ומוסיפים: \u0003ותו לא מידי\u0004 \u0005[ושוב אין\u0006 לומר על כך \u0005דבר].\u0006","ושבים לחבורת החכמים שישבה ודנה בענין הקודם. \u0003הדור יתבי וקמבעיא להו\u0004 \u0005[שוב היו יושבים ונשאלה להם]\u0006 שאלה זו: \u0003דמי עבודה זרה ביד גוי\u0004 שמכר עבודה זרה, \u0003מהו\u0004 דינם? \u0003מי\u0004 \u0005[האם]\u0006 \u0003תופסת דמיה ביד גוי\u0004 שדמיה נאסרים כמו ביד ישראל, \u0003או לא?\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב נחמן: מסתברא\u0004 \u0005[מסתבר]\u0006 ש\u0003דמי עבודה זרה ביד גוי מותרין,\u0004 ומה הראיה? \u0003מדהנהו דאתו לקמיה\u0004 \u0005[מאותם\u0006 גוים \u0005שבאו לפני]\u0006 \u0003רבה בר אבוה\u0004 כדי להתגייר, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003זילו זבינו\u0004 \u0005[לכו\u0006 ו\u0005מכרו]\u0006 \u0003כל מה דאית לכו\u0004 \u0005[שיש לכם],\u0006 ובכלל זה גם עבודה זרה, \u0003ותו איתגיירו\u0004 \u0005[וחזרו\u0006 אלי \u0005והתגיירו],\u0006","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 האם לא \u0003משום דקסבר\u0004 \u0005[שהוא סבור]:\u0006 \u0003דמי עבודה זרה ביד גוי מותרין,\u0004 ולכן הציע להם למכור תחילה את העבודה זרה שברשותם, כדי שאחר כך כשיתגיירו יוכלו להשתמש בדמיהם? ודוחים: \u0003ודלמא שאני התם\u0004 \u0005[ושמא שונה שם],\u0006 ש\u0003כיון דדעתיה לאיגיורי\u0004 \u0005[שדעתו להתגייר]\u0006 \u0003ודאי בטלה\u0004 את העבודה הזרה הזו, וכשמוכר אותה — היתר הוא מוכר!","\u0003אלא\u0004 יש להביא ראיה \u0003מהכא\u0004 \u0005[מכאן],\u0006 ששנינו: \u0003ישראל שהיה נושה בגוי\u0004 שהיה הגוי חייב לו \u0003מנה, ומכר\u0004 הגוי \u0003עבודה זרה ו\u0004מהכסף שקיבל \u0003הביא לו\u0004 את פרעון חובו, או מכר \u0003יין נסך והביא לו\u0004 — הרי זה \u0003מותר. אבל אם אמר לו\u0004 הגוי בפירוש: \u0003\"המתן לי עד שאמכור עבודה זרה ואביא לך\u0004 את כספך\", או \"אמכור \u0003יין נסך ואביא לך\"\u0004 — \u0003אסור.\u0004 הרי שדמי עבודה זרה ביד הגוי מותרים.","ושואלים: \u0003מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[\u0006ב\u0005מה שונה ההתחלה ו\u0006ב\u0005מה שונה הסוף]?\u0006 מדוע במקרה האחרון אסור? \u0003אמר רב ששת: סיפא\u0004 \u0005[בסוף]\u0006 נאסר, \u0003משום דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003כי\u0004 \u0005[כמו]\u0006 ש\u0003רוצה בקיומו,\u0004 שכיון שיודע שהגוי צריך למכור אותם כדי לפרוע לו את החוב, מעוניין הישראל שהעבודה זרה או יין הנסך ישארו קיימים עד שימכרם הגוי.","ושואלים: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003רוצה בקיומו כהאי גוונא\u0004 \u0005[בכגון זה]\u0006 \u0003מי אסיר\u0004 \u0005[האם\u0006 הוא \u0005אסור]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 שני אחים, האחד \u0003גר ו\u0004השני \u0003גוי שירשו\u0004 את \u0003אביהן\u0004 ה\u0003גוי, גר יכול לומר לו\u0004 לאחיו הגוי: \u0003\"טול אתה\u0004 את כל ה\u0003עבודה זרה ואני\u0004 אטול כנגדה \u0003מעות\",\u0004 וכן \u0003\"טול אתה יין נסך ואני פירות\".\u0004 וכל זה כשלא חלקו עדיין, אבל \u0003אם משבאו\u0004 כבר עבודה זרה או יין נסך \u0003לרשות הגר\u0004 — \u0003אסור.\u0004 הרי שלמרות שהגר רוצה בקיומה עד שימכרנה אחיו הגוי — מותר הדבר!","\u0003אמר רבא בר עולא: מתניתין\u0004 \u0005[משנתנו]\u0006 עוסקת \u0003בעבודה זרה\u0004 העשויה ממתכת יקרה \u0003המתחלקת לפי שבריה, ש\u0004גם אם היתה נשברת אין זה משנה את ערכה, ואין הגר חפץ כלל בקיומה.","ושואלים: \u0003תינח\u0004 \u0005[נניח]\u0006 הסבר זה לגבי \u0003עבודה זרה, יין נסך מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי אין מקרה שאינו רוצה בקיומו של היין עד שיימכר! ומשיבים: מדובר \u0003בחרס הדרייני\u0004 שהוא ספוג ביין נסך, שמשתמשים בו על ידי שריית החרס במים, ולכן לא איכפת לו שיישבר, שהרי היין נמצא בתוך החרס בכל מקרה.","ושואלים: \u0003והלא\u0004 בכל זאת \u0003רוצה בקיומו, שלא יגנובו ושלא יאבדו!\u0004 \u0003אלא אמר רב פפא: ירושת הגר קאמרת\u0004 \u0005[אומר אתה]?\u0006 ממשנה זו רוצה אתה להוכיח? \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003ירושת הגר, דאקילו\u0004 \u0005[שהקלו]\u0006 \u0003בה רבנן\u0004 \u0005[חכמים],\u0006 \u0003גזירה שמא יחזור לקלקולו\u0004 אם יאסרו עליו לרשת את אביו מחמת חמדת הממון. אבל בכל מקרה אחר שרוצה בקיומו — אסור."],["\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003במה דברים אמורים\u0004 שמותר לגר ולגוי להתחלק ברכוש משותף שיש בו עבודה זרה? ברכוש \u0003שירשו, אבל\u0004 אם \u0003נשתתפו\u0004 כלומר, אם היתה שותפות ביניהם — \u0003אסור.\u0004","ושבים לחבורת החכמים שישבו יחד, רב נחמן ועולא ואבימי בר פפי, עם ר' חייא בר אמי. \u0003הדור יתבו וקמיבעיא להו\u0004 \u0005[שוב היו יושבים ונשאלה להם]\u0006 שאלה: שנינו שגוי יכול לבטל עבודה זרה של גוי, \u0003גר תושב\u0004 (שהוא גוי שאינו עובד עבודה זרה) \u0003מהו\u0004 דינו לענין \u0003שיבטל עבודה זרה?\u0004 וצדדי השאלה: האם אנו אומרים שדווקא מי \u0003דפלח\u0004 \u0005[שעובד]\u0006 עבודה זרה — הוא \u0003מבטיל\u0004 (יכול לבטל) אותה, \u0003דלא פלח\u0004 \u0005[שאינו עובד\u0006 אותה\u0005]\u0006 — \u0003לא מבטיל\u0004 אותה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כל דבר מיניה מבטיל, והאי בר מיניה הוא\u0004 \u0005[כל ש\u0006הוא \u0005בן מינו מבטל, וזה בן מינו הוא]\u0006 שהרי הוא גוי?","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב נחמן: מסתברא\u0004 \u0005[מסתבר\u0006 לומר\u0005],\u0006 \u0003דפלח\u0004 \u0005[\u0006מי \u0005שעובד]\u0006 — \u0003מבטיל\u0004 \u0005[מבטל],\u0006 מי \u0003דלא פלח\u0004 \u0005[שאינו עובד]\u0006 — \u0003לא מבטיל\u0004 \u0005[\u0006אינו מבטל].","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: \u0003ישראל שמצא עבודה זרה בשוק, עד שלא באתה לידו\u0004 — \u0003אומר לגוי ומבטלה, משבאתה לידו\u0004 — \u0003אינו אומר לגוי ומבטלה.\u0004 ויכול אדם לומר לסתם גוי לבטלה, \u0003מפני שאמרו\u0004 חכמים: \u0003גוי מבטל עבודה זרה שלו ושל חבירו בין עובדה ובין שאין עובדה.\u0004","ונברר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עובדה\", ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"שאינו עובדה\"? אילימא אידי ואידי\u0004 \u0005[אם תאמר זה וזה]\u0006 \u0003גוי,\u0004 אלא \"שאינו עובדה\" הוא זה שעובד עבודה זרה אחרת, אם כן \u0003היינו\u0004 \u0005[הרי זה]\u0006 מה שנאמר קודם לכן שגוי מבטל \u0003שלו ושל חבירו! אלא לאו\u0004 \u0005[האם לא]\u0006 נפרש כך: \u0003\"עובדה\"\u0004 — פירושו \u0003גוי, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"שאינו עובדה\"? גר תושב,\u0004 שאינו עובד כלל עבודה זרה, \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי \u0003גר תושב נמי\u0004 \u0005[גם כן]\u0006 \u0003מבטל!\u0004","ודוחים: \u0003לא, לעולם אימא לך\u0004 \u0005[אומר לך]\u0006 בפירוש \"עובדה\" ו\"שאינו עובדה\": \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 מדובר ב\u0003גוי, ודקאמרת\u0004 \u0005[ו\u0006מה \u0005שאמרת]:\u0006 \u0003היינו \"שלו ושל חבירו\"\u0004 שנאמר בתחילה! יש להסביר: \u0003רישא\u0004 \u0005[בתחילה]\u0006 מדובר ששניהם עובדים לאותה עבודה זרה, כגון \u0003זה וזה\u0004 עובדים \u0003לפעור, ו\u0004כן \u0003זה וזה\u0004 עובדים \u0003למרקוליס,\u0004 ואומרת הברייתא שביכולתו לבטל עבודה זרה השייכת לאחר. \u0003סיפא\u0004 \u0005[בסוף],\u0006 בחלוקה בין \"עובדה\" ל\"שאינו עובדה\", מדובר ש\u0003זה\u0004 עובד \u0003לפעור וזה למרקוליס,\u0004 לומר שאף על פי שאינו עובדה כלל, מכל מקום יכול לבטלה. אבל על כל פנים הוא צריך להיות עובד עבודה זרה, מה שאין כן גר תושב.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 מברייתא: \u0003איזהו גר תושב? כל שקיבל עליו בפני שלשה חברים\u0004 כלומר, אנשים כשרים בישראל \u0003שלא לעבוד עבודה זרה,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003וחכמים אומרים: כל שקיבל עליו שבע מצו‍ת שקבלו עליהם בני נח.\u0004","\u0003אחרים אומרים: אלו לא באו לכלל גר תושב,\u0004 אלא עדיין הם בגדר גוים. \u0003אלא איזהו גר תושב? זה גר אוכל נבילות, שקבל עליו לקיים כל מצו‍ת האמורות בתורה חוץ מאיסור\u0004 \u0003נבילות.\u0004","על כל פנים, ככל שתהיה הגדרתו של גר תושב, \u0003מייחדין\u0004 (מניחים לבד) \u0003אצלו יין\u0004 לזמן קצר, בלא שיהא שם ישראל משגיח, \u0003ואין מפקידין אצלו יין\u0004 לזמן מרובה, \u0003ואפילו בעיר שרובה ישראל, אבל מייחדין אצלו יין ואפילו בעיר שרובה גוים. שמנו\u0004 דינו \u0003כיינו.\u0004","ותוהים: \u0003שמנו כיינו סלקא דעתך\u0004 \u0005[עולה על דעתך]?\u0006 \u0003שמן מי קא הוי\u0004 \u0005[האם הוא נעשה]\u0006 \u0003יין נסך?\u0004 ואם כן, כיצד יכול להיות שמנו כיינו? \u0003אלא\u0004 יש לתקן: \u0003יינו\u0004 דינו \u0003כשמנו,\u0004 שמותר בהנאה ואסור באכילה.","וממשיכה הברייתא: \u0003ולשאר כל דבר הרי הוא כגוי. רבן שמעון אומר: יינו יין נסך, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהוא אומר שיינו \u0003מותר בשתיה.\u0004 עד כאן הברייתא.","\u0003קתני מיהא\u0004 \u0005[שנה על כל פנים]:\u0006 \u0003ולשאר כל דבריו הרי הוא כגוי, למאי הלכתא\u0004 \u0005[למה\u0006 לאיזו \u0005הלכה]\u0006 נאמר הדבר? \u0003לאו\u0004 \u0005[האם לא]\u0006 ש\u0003מבטל עבודה זרה כגוי? אמר רב נחמן בר יצחק: לא,\u0004 לענין \u0003ליתן רשות ולבטל רשות\u0004 בדין עירובי חצרות בשבת.","\u0003וכדתניא\u0004 \u0005[וכמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003ישראל משומד\u0004 ש\u0003משמר שבתו בשוק\u0004 כלומר, שעדיין שומר שבת בפרהסיא — \u0003מבטל רשות\u0004 שיש לו בחצר המשותפת, כדי שיוכלו לטלטל בתוכה, כדין רשות היחיד. אבל ישראל משומד \u0003שאין משמר שבתו בשוק\u0004 אלא מחלל שבת בפרהסיא — \u0003אין מבטל רשות, מפני שאמרו: ישראל נותן רשות ומבטל רשות,\u0004 והנתינה הזו מועילה לענין עירובין בשבת, שאם לא נשתתף בעירוב החצר יכול לבטל רשותו ויהו דיירי החצר מותרים לטלטל בה.","\u0003ו\u0004אולם \u0003בגוי\u0004 אין הדבר מועיל — \u0003עד שישכור\u0004 ממנו הישראל את רשותו בחצר. \u0003כיצד\u0004 ישראל נותן רשות ומבטל רשות? אם \u0003אומר לו\u0004 למי שדר עמו בחצר: \u0003\"רשותי קנויה לך\",\u0004 או \u0003\"רשותי מבוטלת לך\"\u0004 — \u0003קנה, ואין צריך לזכות\u0004 על ידי קנין אחר.","מסופר, \u0003רב יהודה שדר ליה קורבנא\u0004 \u0005[שלח לו מתנה]\u0006"],["\u0003ל\u0004גוי אחד שנקרא \u0003אבידרנא ביום אידם\u0004 (חגם) של הגוים, \u0003אמר: ידענא ביה דלא פלח\u0004 \u0005[יודע אני בו שאינו עובד]\u0006 \u0003לעבודה זרה,\u0004 ולכן אין לו דין גוי לענין זה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף, והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003איזהו גר תושב? כל שקיבל עליו בפני שלשה חברים שלא לעבוד עבודה זרה,\u0004 ובוודאי אבידרנא זה לא קיבל עליו בפני ישראל! אמר לו רב יהודה: \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 — הרי זה לענין \u0003להחיותו,\u0004 שאם קיבל עליו לפני שלושה מישראל מצוה לדאוג לקיומו ורווחתו אם הוא זקוק לכך.","הקשה לו רב יוסף, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה אמר ר' יוחנן: גר תושב שעברו עליו שנים עשר חדש ולא מל, הרי הוא כמין\u0004 (כופר) \u0003שבאומות,\u0004 והרי אבידרנא זה וודאי לא מל! ענה לו: \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003כגון ש\u0004אותו גוי שרצה להיות גר תושב \u0003קיבל עליו למול,\u0004 והתחרט \u0003ולא מל,\u0004 ובמקרה זה אנו סבורים שבגלל כפירה הוא שלא מל, אבל סתם גר תושב אינו נזקק לכך.","כיוצא בזה מסופר, \u0003רבא אמטי ליה קורבנא\u0004 \u0005[הביא לו מתנה]\u0006 \u0003ל\u0004שר אחד שנקרא \u0003בר שישך ביום אידם\u0004 (חגם) של הגוים, \u0003אמר: ידענא ביה דלא פלח\u0004 \u0005[יודע אני בו שאינו עובד]\u0006 \u0003לעבודה זרה. אזל\u0004 \u0005[הלך]\u0006 רבא אליו \u0003אשכחיה\u0004 \u0005[\u0006ו\u0005מצא אותו\u0006 את בר שישך\u0005]\u0006 \u0003דיתיב עד צואריה בוורדא\u0004 \u0005[ש\u0006הוא \u0005יושב עד צווארו ב\u0006שמן \u0005ורד]\u0006 \u0003וקיימן\u0004 \u0005[ועומדות]\u0006 \u0003זונות ערומות קמיה\u0004 \u0005[לפניו]\u0006 לשמשו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 בר שישך לרבא: \u0003אית לכו כהאי גוונא לעלמא דאתי\u0004 \u0005[יש לכם\u0006 היהודים \u0005כגון זה בעולם הבא\u0006 שלכם\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003דידן עדיפא טפי מהאי\u0004 \u0005[\u0006עולם הבא \u0005שלנו עדיף יותר מזה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003טפי מהאי מי הוה\u0004 \u0005[יותר מזה האם יכול להיות]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003אתון איכא עלייכו אימתא דמלכותא, אנן לא תיהוי עלן אימתא דמלכותא\u0004 \u0005[אתם יש עליכם אימת המלכות, אנו לא תהיה עלינו\u0006 בעולם הבא \u0005אימת המלכות].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 בר שישך: \u0003אנא מיהא מאי אימתא דמלכותא איכא עלי\u0004 \u0005[אני על כל פנים איזו אימת מלכות יש עלי]?\u0006 שאני אדם גדול ואיש אינו מעיז להציק לי.","\u0003עד דיתבי\u0004 \u0005[ש\u0006הם \u0005יושבים\u0006 שם\u0005]\u0006 \u0003אתא ההוא פריסתקא דמלכא\u0004 \u0005[בא שליח אחד של המלך],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לבר שישך: \u0003קום, דקבעי לך מלכא\u0004 \u0005[שצריך אותך המלך].\u0006 \u0003כי נפיק ואזיל\u0004 \u0005[כאשר יצא\u0006 בר שישך \u0005והלך\u0006 משם\u0005],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לרבא: \u0003עינא דבעי למיחזי לכו בישותא\u0004 \u0005[עין שרוצה לראות לכם רע]\u0006 \u0003תיפקע,\u0004 שהרי רואים כמה אתם צודקים, שמיד הוכחה אמיתות דבריך שאימת המלך עלי, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אמן,\u0004 ומסופר \u0003פקע עיניה\u0004 \u0005[פקעה\u0006 התבקעה \u0005עינו]\u0006 של \u0003בר שישך\u0004 שהיתה עינו רעה בישראל.","\u0003אמר רב פפי: איבעי ליה למימרא ליה מהאי קרא\u0004 \u0005[היה צריך\u0006 רבא \u0005לומר לו\u0006 תשובה \u0005מפסוק זה]:\u0006 \u0003\"בנות מלכים ביקרותיך נצבה שגל לימינך בכתם אופיר\"\u0004 (תהלים מה, י), שלעתיד לבוא בנות מלכים ישרתו את בני ישראל. \u0003אמר רב נחמן בר יצחק: איבעי ליה למימרא ליה מהכא\u0004 \u0005[היה צריך לומר לו מכאן,\u0006 מפסוק זה\u0005]\u0006 מה השכר הצפוי לבני ישראל לעתיד לבוא: \u0003\"עין לא ראתה אלהים זולתך יעשה למחכה לו\"\u0004 (ישעיה סד, ג).","שנינו במשנה שאם \u0003שכרו\u0004 הגוי \u0003לעשות עמו מלאכה אחרת\u0004 ובתוך מלאכתו אמר לו להעביר לו חבית של יין נסך — שכרו מותר. ומעירים: \u0003ו\u0004מלשונה הכללית של המשנה יש להבין כי הדין כן \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא אמר ליה\u0004 \u0005[לו]\u0006 דבר זה \u0003לעיתותי ערב\u0004 כלומר, בסוף יום העבודה.","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005],\u0006 ששנינו בברייתא: גוי \u0003השוכר את הפועל, ולעיתותי ערב אמר לו: \"העבר חבית של יין נסך ממקום למקום\"\u0004 — \u0003שכרו מותר.\u0004 ונדייק משם: \u0003טעמא\u0004 \u0005[הטעם],\u0006 דווקא כש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003לעיתותי ערב\u0004 — \u0003אין\u0004 \u0005[\u0006הדין \u0005כן],\u0006 שהוא מותר, מפני שברור שגמר את מלאכתו עליה הוא מקבל את שכרו, והעברת חבית זו אינה שייכת לכך. אבל אם עשה כן במשך \u0003כולי יומא\u0004 \u0005[כל היום]\u0006 — \u0003לא!\u0004","\u0003אמר אביי: כי תנן נמי מתניתין\u0004 \u0005[כאשר שנינו גם כן משנתנו],\u0006 במקרה ש\u0003אמר לעיתותי ערב תנן\u0004 \u0005[שנינו].\u0006 \u0003רבא אמר: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שנאסר השכר אם לא היה זה לעיתותי ערב, הרי זה במקרה ש\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"העבר לי מאה חביות במאה פרוטות\",\u0004 שאז הבאת כל החביות נחשבת כדבר אחד, ואם היתה אחת מהן יין נסך כל שכרו נאסר משום שכר יין נסך שמעורב בו, \u0003הא\u0004 \u0005[זה]\u0006 שמותר בכל אופן — במקרה ש\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"העבר לי חבית חבית בפרוטה\",\u0004 ששכר כל חבית משולם לעצמו.","\u0003והתניא\u0004 \u0005[וכן שנויה\u0006 ברייתא\u0005]:\u0006 \u0003השוכר את הפועל, ואמר לו: \"העבר לי מאה חביות במאה פרוטות\", ונמצאת חבית\u0004 אחת \u0003של יין נסך ביניהן\u0004 — \u0003שכרו אסור\u0004 משום תערובת זו, אבל אם אמר לו: \u0003\"חבית חבית בפרוטה\", ונמצאת חבית של יין נסך ביניהן\u0004 — \u0003שכרו מותר.\u0004","שנינו במשנה: גוי \u0003השוכר את החמור להביא עליה יין נסך\u0004 — \u0003שכרו אסור,\u0004 אבל אם שכרה כדי לישב עליה, אף על פי שהניח הגוי לגינו (כד) של יין נסך עליו — הרי זה מותר. ושואלים: \u0003הא תו\u0004 \u0005[זו עוד]\u0006 \u0003למה לי? היינו רישא\u0004 \u0005[הרי זו\u0006 אותה הלכה \u0005שבתחילה],\u0006 שהעיקרון הוא אחד, אלא רק בשינוי המעשה! ומשיבים: \u0003סיפא איצטריכא ליה\u0004 \u0005[הסוף הוצרך לו]\u0006 לומר: \u0003שכרה לישב עליה, אף על פי שהניח גוי לגינו עליה\u0004 — \u0003שכרו מותר,\u0004 שלא שילם כלל עבור הנחת הלגין.","ומדייקים: \u0003למימרא, דלגין לאו דינא הוא לאותוביה\u0004 \u0005[האם לומר\u0006 מכאן, \u0005שהלגין אין דינו להושיבו עליו,\u0006 על החמור\u0005],\u0006 ומשום כך, הולכת הלגין אינה בכלל תנאי ההובלה?","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מקשים על כך] ממה ששנינו בברייתא \u0005:\u0006 \u0003השוכר את החמור\u0004 — \u0003שוכר מניח עליה\u0004 על החמור את \u0003כסותו ולגינתו\u0004 (כדו) \u0003ומזונותיו של אותו הדרך, מכאן ואילך\u0004 (מעבר לכך) אם רוצה להניח דברים נוספים על אלה \u0003חמר מעכב עליו\u0004 שלא יכביד על החמור. ומצד אחר \u0003חמר מניח עליה\u0004 על החמור \u0003שעורים ותבן ומזונותיו של אותו היום, מכאן ואילך\u0004 אם רוצה להוסיף — \u0003שוכר מעכב עליו\u0004 שלא יפריע לחמור!","\u0003אמר אביי: נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003לגין דינא\u0004 \u0005[דין]\u0006 \u0003הוא לאותובי\u0004 \u0005[להושיב],\u0006 \u0003מיהא אי לא מותיב ליה, מי אמרינן ליה\u0004 \u0005[על כל פנים אם לא יושיב אותו\u0006 את הלגין, \u0005האם נאמר לו\u0006 השוכר\u0005]:\u0006 \u0003נכי ליה אגרא דלגינתו\u0004 \u0005[נכה לו את השכר של הלגין שלו\u0006 שלא הניח על החמור\u0005]?\u0006 ומכיון שבעל החמור אינו מנכה לו אם לא הניח את הלגין, הרי גם כאשר הוא מניחו — אינו מתחייב עליו משום שכר יין נסך.","ולעצם דין הברייתא שואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי דשכיח למזבן\u0004 \u0005[אם שמצוי לקנות\u0006 מזון\u0005]\u0006 במשך הדרך הזו — \u0003חמר נמי לעכב\u0004 \u0005[גם כן יעכב]\u0006 את השוכר שלא יקח מזונות של כל הדרך, אלא רק של יום אחד, \u0003ואי דלא שכיח למזבן\u0004 \u0005[ואם שלא מצוי למכור]\u0006 — \u0003שוכר נמי לא לעכב\u0004 \u0005[גם כן לא יעכב]\u0006 את החמר מלקחת איתו מזונות לכל הדרך!","\u0003אמר רב פפא: לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא למקרה \u0003דשכיח למיטרח ולמזבן מאונא לאונא\u0004 \u0005[שמצוי לטרוח ולקנות מתחנה לתחנה]\u0006 ויספיק לו כדי יום אחד, ה\u0003חמר דרכיה למיטרח ולמזבן\u0004 \u0005[דרכו לטרוח ולקנות]\u0006 בדרך, ולכן אין מתירים לו להניח מזונות כל הדרך על החמור, ואילו ה\u0003שוכר לאו דרכיה למיטרח ולמזבן\u0004 \u0005[אין דרכו לטרוח ולקנות]\u0006 בדרך, ולכן מאפשרים לו לקחת את כל המזונות יחד איתו.","מסופר, \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא\u0004"],["\u0003הוה שפיך להו חמרא\u0004 \u0005[היה שופך להם יין]\u0006 שמכר להם \u0003לגוים\u0004 מן הקנקנים לנאדות שלהם, \u0003ואזיל מעבר להו מעברא\u0004 \u0005[והולך,\u0006 ו\u0005מעביר אותם במעבורת]\u0006 את הגוים, \u0003ויהבו ליה גולפי באגרא\u0004 \u0005[והיו נותנים לו\u0006 את \u0005הקנקנים בשכרו].\u0006 \u0003אתו\u0004 \u0005[באו]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לאביי,\u0004 להתלונן על שהוא משתכר ביינם של גוים, \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003כי קא טרח\u0004 \u0005[כאשר הוא טורח]\u0006 — \u0003בהתירא קא טרח\u0004 \u0005[בהיתר הוא טורח],\u0006 שהרי הוא שופך יין כשר לנאדות, ורק אחר כך היין נאסר בידי הגוים.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 עדיין יש איסור בדבר, מפני שהוא \u0003רוצה בקיומו\u0004 של היין האסור בנאדות, שהרי הוא רוצה ש\u0003לא נצטרו זיקי\u0004 \u0005[יתבקעו הנאדות],\u0006 ואז יצטרך להחזיר להם את הקנקנים שקיבל בשכרו! ומשיבים: מדובר היה במקרה \u0003דמתני בהדייהו\u0004 \u0005[שמתנה איתם]\u0006 שגם אם יתבקעו הנאדות הרי זה על חשבונם, ואת הקנקנים יקבל בכל מקרה. \u0003אי נמי, דמייתו פריסדקי בהדייהו\u0004 \u0005[או גם כן,\u0006 מדובר היה \u0005שמביאים כדים\u0006 ריקים \u0005של חרס איתם],\u0006 כך שאם יתבקעו הנאדות ישפכו את היין לכלים אלה, ולכן לא היה חשוב לו קיומם של הנאדות.","ומקשים עוד: \u0003והא קא מעבר להו מעברא, דקא טרח באיסורא\u0004 \u0005[והרי מעביר אותם במעבורת\u0006 לאחר שכבר נאסר היין, \u0005והוא טורח באיסור]!\u0006 ומשיבים: אין הכוונה שהיה מעביר את היין בעצמו במעבורת, אלא \u0003דאמר ליה למברויא מעיקרא\u0004 \u0005[ש\u0006היה \u0005אומר לו לבעל המעבורת מתחילה]\u0006 שיעביר את הקונים והחביות בחינם. \u0003אי נמי, דנקיטי ביה קיטרי\u0004 \u0005[או גם כן, שיש לו קשר,\u0006 סימן\u0005]\u0006 עם בעל המעבורת, והוא מעביר בחינם אנשים אלה. ועל כל פנים, הוא עצמו לא היה טורח בהם.","\u0003יין נסך שנפל על גבי ענבים\u0004 — \u0003ידיחן\u0004 במים \u0003והן מותרות, ואם היו\u0004 הענבים \u0003מבוקעות\u0004 שהיין נבלע בתוכן — \u0003אסורות. נפל\u0004 יין נסך \u0003על גבי תאנים או על גבי תמרים, אם יש בהן\u0004 מן היין הזה \u0003בנותן טעם\u0004 — \u0003אסור. ומעשה בביתוס בן זונן שהביא גרוגרות בספינה, ונשתברה חבית של יין נסך ונפל על גביהן, ושאל לחכמים והתירום,\u0004 כפי שיבואר בגמרא מדוע.","\u0003זה הכלל: כל ש\u0004יש \u0003בהנאתו בנותן טעם\u0004 לשבח בדבר שנתערב בו — הרי זה \u0003אסור, כל שאין בהנאתו בנותן טעם\u0004 לשבח — \u0003מותר, כגון\u0004 למשל \u0003חומץ שנפל על גבי גריסין\u0004 שאינו מוסיף טעם לשבח.","במשנה הובאה תחילה ההלכה כי איסור הנותן טעם בדבר היתר — הריהו אוסרו, ואילו לאחר מכן הובא מעשה ממנו מוכח שהדבר מותר. ותמהים: וכי מביאים \u0003מעשה לסתור\u0004 ההלכה שנאמרה קודם? ומשיבים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך\u0006 היא \u0005שנויה]:\u0006 \u0003אם נותן טעם לפגם הוא\u0004 — \u0003מותר, ומעשה נמי\u0004 \u0005[גם כן]\u0006 \u0003בביתוס בן זונן שהיה מביא גרוגרות בספינה, ונשתברה חבית של יין נסך ונפל על גביהן, ובא מעשה לפני חכמים והתירום,\u0004 כי יין הגרוגרות הוא נותן טעם לפגם.","מסופר, \u0003ההוא כרי דחיטי דנפל עליה חביתא\u0004 \u0005[כרי אחד\u0006 ערימה \u0005של חיטים שנפלה עליו חבית]\u0006 של \u0003יין נסך, שרייה\u0004 \u0005[התיר אותו]\u0006 \u0003רבא לזבוניה\u0004 \u0005[למכור]\u0006 אותו כרי חיטים \u0003לגוים,\u0004 שלא נאסר בהנאה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבה בר ליואי לרבא\u0004 ממה ששנינו: \u0003בגד שאבד בו כלאים\u0004 כלומר, בגד צמר שאנו יודעים שיש בו פשתן, אבל לא ניכר היכן הוא — \u0003הרי זה לא ימכרנה לגוי, ולא יעשנה מרדעת לחמור, אבל עושה אותו\u0004 את הבגד הזה \u0003תכריכין למת מצוה\u0004 (שאין לו קוברים) שהרי המת פטור מן המצוות.","\u0003לגוי מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 מוכרים בגד כזה? \u0003דלמא אתי לזבוניה\u0004 \u0005[שמא יבוא למכור אותו ]\u0006 \u0003לישראל\u0004 והקונה לא ידע שיש בו איסור וילבשנו, \u0003הכא נמי אתי לזבוניה\u0004 \u0005[כאן גם כן\u0006 בכרי חיטים זה, \u0005יבוא\u0006 הגוי \u0005למכור אותו]\u0006 \u0003לישראל!\u0004","\u0003הדר\u0004 \u0005[חזר]\u0006 רבא מדבריו ו\u0003שרא למיטחינהו ולמפינהו ולזבונינהו\u0004 \u0005[והתיר לטוחנן\u0006 את החיטים הללו \u0005ולאפות\u0006 מהן לחם \u0005ולמוכרם]\u0006 \u0003לגוים שלא בפני ישראל,\u0004 כך שלא יבואו ישראל לקנות מהם, לפי שהם פת גוים.","ומקשים על פסקו של רבא, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003יין נסך שנפל על גבי ענבים\u0004 — \u0003ידיחן והן מותרות, ואם היו מבוקעות\u0004 — \u0003אסורות.\u0004 ומדייקים: אם היו \u0003מבוקעות\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003שאין מבוקעות\u0004 — \u0003לא,\u0004 ואם כן מפני מה היה לחשוש כאן שנפל על גבי החיטים? הרי די להן בהדחה! \u0003אמר רב פפא: שאני חיטי\u0004 \u0005[שונות חיטים],\u0006 \u0003הואיל ואגב צירייהו\u0004 \u0005[כיון\u0006 שיש בהן מעצם ברייתן \u0005סדקים]\u0006 \u0003כמבוקעות דמיין\u0004 \u0005[\u0006הן \u0005נחשבות],\u0006 שהיין נכנס בסדקים ונבלע בהן."],["\u0003חמרא עתיקא בענבי\u0004 \u0005[יין\u0006 נסך \u0005ישן\u0006 שנפל \u0005ב\u0006תוך \u0005ענבים]\u0006 \u0003דברי הכל\u0004 שיעורו לאסור אותם הוא \u0003בנותן\u0004 בהם \u0003טעם. חמרא חדתא בענבי\u0004 \u0005[יין חדש\u0006 של נסך, שזה עתה נסחט, שנפל \u0005בענבים],\u0006 \u0003אביי אמר:\u0004 אוסר \u0003במשהו, ורבא אמר:\u0004 אוסר \u0003בנותן טעם.\u0004","ומסבירים את טעמיהם: \u0003אביי אמר במשהו,\u0004 משום שהוא סבור כי בענייני תערובות \u0003בתר טעמא אזלינן\u0004 \u0005[אחר הטעם אנו הולכים],\u0006 \u0003אידי ואידי חד טעמא\u0004 \u0005[זה וזה,\u0006 היין והענבים, \u0005טעם אחד]\u0006 \u0003הוא,\u0004 \u0003דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003מין במינו, ו\u0004כלל בידינו כי \u0003מין במינו\u0004 אוסר \u0003במשהו. ו\u0004אילו","\u0003רבא אמר בנותן טעם,\u0004 שהוא סבור: \u0003בתר שמא אזלינן\u0004 \u0005[אחר השם אנו הולכים],\u0006 \u0003והאי שמא לחוד והאי שמא לחוד\u0004 \u0005[וזה שם לחוד,\u0006 שהוא נקרא יין, \u0005וזה שם לחוד,\u0006 שנקרא ענבים\u0005],\u0006 \u0003והוה ליה\u0004 \u0005[והרי הוא]\u0006 \u0003מין בשאינו מינו, ומין בשאינו מינו\u0004 אוסר רק \u0003בנותן טעם.\u0004","ומביאים ראיה לשיטת רבא, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003יין נסך שנפל על גבי ענבים\u0004 אם היו מבוקעות — אסורות. ומקדימים: \u0003קא סלקא דעתין\u0004 \u0005[עולה על דעתנו\u0006 לומר\u0005]\u0006 שמדובר ב\u0003חמרא חדתא בענבי\u0004 \u0005[יין חדש בענבים],\u0006 \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה שאוסר \u0003בנותן טעם?\u0004 ואם כן אחר השם אנו הולכים, שהרי הטעם במקרה זה אחד הוא! ודוחים: \u0003לא, במשהו.\u0004","על כך מקשים: \u0003הא מדקתני סיפא\u0004 \u0005[הרי מ\u0006מה \u0005ששנה בסופה\u0006 של המשנה\u0005]\u0006 \u0003\"זה הכלל: כל שבהנאתו בנותן טעם\u0004 — \u0003אסור, כל שאין בהנאתו בנותן טעם\u0004 — \u0003מותר\", מכלל\u0004 הדברים אתה למד ש\u0003בנותן טעם עסקינן\u0004 \u0005[עוסקים אנו\u0006 במשנה זו\u0005]!\u0006","\u0003ואביי,\u0004 כיצד הוא מתרץ את הדברים? לדעתו \u0003מתניתין בחמרא עתיקא בענבי\u0004 \u0005[משנתנו\u0006 עוסקת \u0005ביין ישן\u0006 שנפל \u0005בענבים],\u0006 שאז ודאי אין טעמם אחד, ואינו אוסר אלא בנותן טעם.","ובהתאם לשיטותיהם נחלקו אביי ורבא גם בנושא הבא: \u0003חלא דחמרא וחלא דשיכרא\u0004 \u0005[חומץ יין וחומץ שיכר]\u0006 אחד של איסור ואחד של היתר, \u0003ו\u0004כן \u0003חמירא דחיטי וחמירא דשערי\u0004 \u0005[שאור של חיטים ושאור של שעורים]\u0006 שנתערבו זה בזה, \u0003אביי אמר:\u0004 הרי הוא אוסר \u0003בנותן טעם,\u0004 משום ש\u0003בתר טעמא אזלינן\u0004 \u0005[אחר הטעם אנו הולכים],\u0006 \u0003והאי טעמא לחוד והאי טעמא לחוד\u0004 \u0005[וזה טעם לחוד וזה טעם לחוד],\u0006 \u0003והוה ליה\u0004 \u0005[והרי הוא]\u0006 \u0003מין בשאינו מינו, ומין בשאינו מינו בנותן טעם.\u0004","\u0003ורבא אמר: במשהו,\u0004 לשיטתו שהוא סבור: \u0003בתר שמא אזלינן\u0004 \u0005[אחר השם אנו הולכים],\u0006 \u0003והאי חלא מיקרי והאי חלא מיקרי\u0004 \u0005[וזה חומץ נקרא וזה חומץ נקרא],\u0006 \u0003ו\u0004כן \u0003האי חמירא מיקרי והאי חמירא מיקרי\u0004 \u0005[וזה שאור נקרא וזה שאור נקרא],\u0006 \u0003והוה ליה\u0004 \u0005[והרי הוא]\u0006 \u0003מין במינו, וכל מין במינו במשהו.\u0004","\u0003אמר אביי: מנא אמינא לה דבתר טעמא אזלינן\u0004 \u0005[מנין אני אומר אותה\u0006 את סברתי \u0005שאחר הטעם אנו הולכים]?\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003תבלין\u0004 (תבלינים) אסורים, שהם \u0003שנים ושלשה שמות\u0004 כלומר, שלכל אחד יש שם אחר, \u0003ו\u0004אולם \u0003הן מין אחד, או מין שלשה\u0004 (שלושה מינים) — הרי הם \u0003אסורין ומצטרפין\u0004 זה לזה לאסור את התבשיל אם יש בהם יחד שיעור איסור. \u0003ואמר חזקיה\u0004 מדוע שלושה מינים מצטרפים? \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003במיני מתיקה עסקינן\u0004 \u0005[עוסקים אנו],\u0006 ומשום כך הם מצטרפים — \u0003הואיל וראוין למתק בהן את הקדירה,\u0004 ולענין זה אין הבדל בטעמיהם. ומעתה, \u0003אי אמרת בשלמא בתר טעמא אזלינן\u0004 \u0005[נניח אם אומר אתה אחר הטעם אנו הולכים]\u0006 — \u0003כולי חד טעמא\u0004 \u0005[הכל טעם אחד]\u0006 \u0003הוא\u0004 נחשב, \u0003אלא אי אמרת בתר שמא אזלינן\u0004 \u0005[אם אתה אומר אחר השם אנו הולכים],\u0006 מדוע יצטרפו, גם אם כולם באים למתק? והרי \u0003האי שמא\u0004 \u0005[זה\u0006 יש לו \u0005שם]\u0006 \u0003לחוד והאי שמא\u0004 \u0005[וזה\u0006 יש לו \u0005שם]\u0006 \u0003לחוד!\u0004","\u0003ורבא אמר לך\u0004 \u0005[יכול היה לומר לך]:\u0006 \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003ר' מאיר היא,\u0004 שסבור שכל האיסורים מצטרפים, גם אם אין להם טעם אחד ולא שם אחד. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר משום\u0004 (בשם) \u0003ר' מאיר: מנין לכל איסורין שבתורה שמצטרפין זה עם זה\u0004 לכדי שיעור אחד? \u0003שנאמר: \"לא תאכל כל תועבה\"\u0004 (דברים יד, ג), ומכאן הוא למד: \u0003כל שתיעבתי לך\u0004 כל דבר שיש בו איסור, שעליך לתעב אותו ולהתרחק ממנו — \u0003הרי הוא בבל תאכל,\u0004 ואם כן, יש לגבי כל האיסורים כולם איסור כולל אחד.","ועוד נחלקו אביי ורבא בענין זה. ותחילה מקדימים: \u0003חלא לגו חמרא\u0004 \u0005[חומץ\u0006 אסור שנפל \u0005לתוך\u0006 חבית \u0005יין]\u0006 \u0003דברי הכל\u0004 הריהו אוסר \u0003בנותן טעם.\u0004 אבל \u0003חמרא לגו חלא\u0004 \u0005[יין\u0006 שנפל \u0005לתוך\u0006 חבית \u0005חומץ]\u0006 שמתוך ריבוי החומץ וחריפותו הוא משפיע על היין, שנעשה ריחו כריח חומץ עוד קודם שנתערב בחומץ, \u0003אביי אמר:\u0004 אוסר \u0003במשהו, ורבא אמר: בנותן טעם.\u0004","ומסבירים את טעמיהם: \u0003אביי אמר\u0004 שאוסר אפילו \u0003במשהו,\u0004"],["כי כל דבר ש\u0003ריחיה חלא וטעמא חמרא\u0004 \u0005[ריחו\u0006 ריח \u0005חומץ ו\u0006טעמו \u0005טעם יין]\u0006 — הרי הוא \u0003חלא\u0004 \u0005[חומץ],\u0006 והואיל והיין כשנפל לחלל החבית של החומץ כבר שינה את ריחו לריח חומץ, נמצא שהוא חומץ, \u0003והוה ליה\u0004 \u0005[ו\u0006משנתערב בחומץ \u0005הרי הוא]\u0006 \u0003מין במינו, וכל מין במינו במשהו.\u0004","\u0003רבא אמר\u0004 שאוסר \u0003בנותן טעם,\u0004 משום שהוא סבור ש\u0003ריחיה חלא וטעמא חמרא\u0004 \u0005[\u0006מה \u0005שריחו חומץ והטעם יין]\u0006 — \u0003חמרא\u0004 \u0005[יין],\u0006 \u0003והוה ליה\u0004 \u0005[והרי הוא\u0006 איפוא\u0005]\u0006 \u0003מין בשאינו מינו, וכל מין בשאינו מינו בנותן טעם.\u0004","\u0003האי בת תיהא\u0004 \u0005[נקב הרחה]\u0006 שנוקבים במגופה כדי להריח את היין, אם היה המריח \u0003גוי ב\u0004יין של \u0003ישראל\u0004 — \u0003שפיר דמי\u0004 \u0005[\u0006הרי זה \u0005מותר],\u0006 שאינו אוסר בהרחה. \u0003ישראל\u0004 להריח \u0003ב\u0004יין של \u0003גוי, אביי אמר: אסור, רבא אמר: מותר.\u0004 ומסבירים את שיטותיהם: \u0003אביי אמר אסור,\u0004 כי הוא סבור ש\u0003ריחא מילתא היא\u0004 \u0005[ריח דבר הוא]\u0006 וכיון שמריח בו הריהו כשותה את האיסור עצמו. ואילו \u0003רבא\u0004 \u0003אמר מותר,\u0004 וטעמו — \u0003ריחא לאו מילתא היא\u0004 \u0005[ריח אינו דבר].\u0006","\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה]\u0006 את סברתי זו ש\u0003ריחא לאו\u0004 \u0005[ריח אינו]\u0006 \u0003כלום הוא\u0004 לענין איסור? \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003תנור שהסיקו בכמון\u0004 (צמח תבלין ריחני) שהיה \u0003של תרומה, ואפה בו את הפת\u0004 — \u0003הפת מותרת, לפי שאין טעם כמון\u0004 נכנס בתוך הפת \u0003אלא\u0004 רק \u0003ריחא\u0004 \u0005[הריח]\u0006 של \u0003כמון,\u0004 וזה אינו אוסר. משמע שריח לבדו אין בו איסור! \u0003ואביי,\u0004 כיצד דוחה הוא הוכחה זו? \u0003שאני התם, דמיקלא איסוריה\u0004 \u0005[שונה שם, שנשרף איסורו],\u0006 שהרי באותו מקרה הריח נכנס בפת לאחר שהכמון האסור נשרף, וריח בלבד שאין בו ממש לא נאסר, אבל במקום שיש לריח עיקר — אף הריח אסור.","\u0003אמר רב מרי,\u0004 מחלוקת אביי ורבא הריהי \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 ששנינו: \u0003הרודה פת חמה\u0004 מן התנור \u0003ונתנה על פי חבית של יין של תרומה, ר' מאיר אוסר\u0004 את הפת לזרים, שהוא סבור שהפת נאסרת מחמת ריח היין, \u0003ור' יהודה מתיר. ר' יוסי מתיר ב\u0004פת \u0003של חיטין ואוסר בשל שעורים, מפני שהשעורים שואבות\u0004 הרבה מאדי היין. ומציעים: \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בזה הם חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' מאיר, \u0005סבור]:\u0006 \u0003ריחא מילתא היא\u0004 \u0005[\u0006ש\u0005ריח דבר הוא],\u0006 \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יהודה, \u0005סבור]:\u0006 \u0003ריחא\u0004 \u0005[ריח]\u0006 \u0003ולא כלום הוא?\u0004","ומעירים: \u0003ל\u0004דעת \u0003רבא ודאי תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, ל\u0004דעת \u0003אביי מי לימא תנאי\u0004 \u0005[האם לומר\u0006 שמחלוקת \u0005תנאים]\u0006 \u0003היא?\u0004","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך אביי: לאו מי איתמר עלה\u0004 \u0005[האם לא נאמר עליה]\u0006 על משנה זו, \u0003אמר רבה בר בר חנה אמר ריש לקיש: בפת חמה וחבית פתוחה\u0004 —"],["\u0003דברי הכל אסורה\u0004 שוודאי ספגה מריח היין, \u0003בפת צוננת וחבית מגופה\u0004 — \u0003דברי הכל מותרת\u0004 הפת, \u0003לא נחלקו אלא בפת חמה וחבית מגופה,\u0004 או \u0003בפת צוננת וחבית פתוחה. והא דידי\u0004 \u0005[וזו שלי]\u0006 כלומר, הדין שאני אוסר בו, בבת תיהא, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003כפת חמה וחבית פתוחה דמי\u0004 \u0005[נחשב],\u0006 והכל מודים שהוא אסור.","שנינו במשנה: \u0003זה הכלל, כל שבהנאתו בנותן טעם\u0004 לשבח הריהו אוסר. אבל כל שנותן טעם לפגם, כגון חומץ של איסור בגריסים — אינו אוסר. \u0003אמר רב יהודה אמר שמואל: הכי הלכתא\u0004 \u0005[כך\u0006 היא \u0005ההלכה].\u0006","\u0003ו\u0004עוד \u0003אמר רב יהודה אמר שמואל: לא שנו אלא שנפל\u0004 החומץ \u0003לתוך גריסין רותחין,\u0004 שאז טעמו פוגם, \u0003אבל\u0004 אם \u0003נפל לתוך גריסין צוננין\u0004 הרי אז החומץ משביח טעם הגריסין, \u0003ו\u0004גם אם אחר כך \u0003הרתיחן\u0004 (חימם את התערובת), \u0003נעשה כמי שהשביח\u0004 מתחילה \u0003ולבסוף פגם, ואסור,\u0004 לפי שמתחילה היה טעמו בהם לשבח.","\u0003וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל מסר כי כך \u0003אמר רבה בר בר חנה אמר ר' יוחנן: לא שנו אלא שנפל לתוך גריסין רותחין, אבל נפל לתוך גריסין צוננין והרתיחן, נעשה כמי שהשביח ולבסוף פגם, ואסור. וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 אמר כן בשם ר' יוחנן. ועוד הוסיף: \u0003וכך היו עושין בערבי שבתות בציפורי\u0004 בגריסין וחומץ, \u0003וקוראין אותם\u0004 בלשון שבח \u0003שחליים.\u0004","\u0003אמר ריש לקיש: נותן טעם לפגם שאמרו\u0004 שאינו אוסר, הגדרתו היא — \u0003לא שיאמרו\u0004 על מאכל זה: \u0003קדירה זו חסירה מלח,\u0004 או \u0003יתירה מלח, חסירה תבלין,\u0004 או \u0003יתירה תבלין,\u0004 ובגלל זה נפגם טעמה על ידי האיסור. \u0003אלא\u0004 איזהו טעם לפגם? \u0003כל שאין\u0004 קדירת התבשיל \u0003חסירה כלום\u0004 מלח או תבלין, \u0003ואינה נאכלת\u0004 רק \u0003מפני\u0004 איסור \u0003זה\u0004 שפגמה.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 בלשון אחרת, ולהקל: \u0003אמר ריש לקיש: נותן טעם לפגם שאמרו, אין אומרין: קדירה זו חסירה מלח, יתירה מלח, חסירה תבלין, יתירה תבלין,\u0004 ומפני זה גרם האיסור לתבשיל שייפגם. \u0003אלא השתא מיהא הא פגמה\u0004 \u0005[עכשיו הרי\u0006 היא \u0005פגומה]\u0006 וכיון שבפועל היא פגומה הרי זה מותר.","ועוד בענין איסור שנתערב בהיתר. \u0003אמר ר' אבהו אמר ר' יוחנן: כל שטעמו ו\u0004גם \u0003ממשו\u0004 של האיסור ניכר בהיתר — \u0003אסור\u0004 לאכילה ו\u0003לוקין עליו, וזהו\u0004 שקיבלנו במסורת, שהאוכל \u0003כזית\u0004 מתערובת האיסור \u0003בכדי אכילת פרס,\u0004 שיש בתערובת שיעור זה של חצי ככר לחם (\"פרס\") נחשב כאילו היה אוכל מן האיסור עצמו."],["אם היה זה רק \u0003טעמו ולא ממשו\u0004 כגון שנימוח התבשיל — הרי הוא \u0003אסור, ו\u0004אולם \u0003אין לוקין עליו, ואם ריבה טעם לפגם\u0004 — \u0003מותר.\u0004","ושואלים, \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 בפשטות: \u0003אם נתן טעם לפגם\u0004 — \u0003מותר!\u0004 ומשיבים: \u0003הא קמשמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו]\u0006 בלשון זאת, \u0003דאף על גב דאיכא מילי אחרנייתא דפגמה בהדיה\u0004 \u0005[שאף על פי שיש דברים אחרים שפוגמים יחד איתו],\u0006 כגון חוסר מלח או עודף תבלין, אין מתחשבים בכך, אלא כיון שפגם האיסור בטעם ההיתר — מותר. \u0003והלכתא כלישנא בתרא\u0004 \u0005[והלכה כלשון אחרונה]\u0006 של \u0003ריש לקיש\u0004 (בעמוד הקודם).","\u0003אמר רב כהנא: מדברי\u0004 האמוראים \u0003כולם\u0004 שהובאו (רב יהודה בשם שמואל, ורבה בר בר חנה, ורב דימי בשם ר' יוחנן, וריש לקיש) \u0003נלמד\u0004 ש\u0003נותן טעם לפגם\u0004 — \u0003מותר. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: בשלמא מכולהו לחיי\u0004 \u0005[נניח\u0006 שאתה אומר \u0005שמכולם\u0006 אפשר ללמוד זאת \u0005בסדר].\u0006 \u0003אלא\u0004 מדברי \u0003ריש לקיש\u0004 כיצד נלמד? הרי \u0003\"אמרו\" קאמר\u0004 \u0005[הוא אמר],\u0006 ומשמע שהוא רק מביא מה שאמרו אחרים, \u0003וליה לא סבירא ליה\u0004 \u0005[והוא\u0006 עצמו \u0005אינו סובר כן]!\u0006","וחוזרים לדון בעיקר דברי רב כהנא, ושואלים: האם \u0003מכלל\u0004 דבריו משמע \u0003דאיכא למאן דאמר\u0004 \u0005[שיש מי שאומר]\u0006 ש\u0003נותן טעם לפגם\u0004 — \u0003אסור?\u0004","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003והתניא\u0004 \u0005[וכן שנויה\u0006 ברייתא\u0005]:\u0006 אחד נותן טעם לפגם ואחד נותן טעם לשבח — \u0003אסור,\u0004 אלו \u0003דברי ר' מאיר. ר' שמעון אומר: לשבח\u0004 — \u0003אסור, ולפגם\u0004 — \u0003מותר.\u0004 הרי שר' מאיר סבור כן.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' מאיר? גמר\u0004 \u0005[לומד\u0006 הוא\u0005]\u0006 \u0003מגיעולי גוים,\u0004 מקדירות שהתבשל בהן מאכל גוים, שהתורה הצריכה הכשר לכלים ששללו ישראל ממדין (במדבר לא, כב —כג), \u0003גיעולי גוים לאו\u0004 \u0005[האם אין\u0006 זה\u0005]\u0006 \u0003נותן טעם לפגם הוא?\u0004 שהרי טעם האוכל שבהם נפגם במשך הזמן ואינו אלא פוגם בתבשיל, \u0003ו\u0004בכל זאת \u0003אסר רחמנא\u0004 \u0005[אסרה\u0006 אותו \u0005התורה],\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 בכל מקרה \u0003לא שנא\u0004 \u0005[אינו שונה],\u0006 ואף טעם לפגם אסור.","\u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' שמעון\u0005]\u0006 שמתיר טעם לפגם, מה הוא משיב לראיה זו? הוא מסביר \u0003כ\u0004דברי \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חייא,\u0004 ש\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חייא: לא אסרה תורה אלא קדירה בת יומא\u0004 \u0005[יום]\u0006 כלומר, שנתבשל בה האיסור בו ביום, שהטעם שהיא נותנת ש\u0003לא לפגם הוא. ואידך\u0004 \u0005[והאחר,\u0006 ר' מאיר\u0005],\u0006 מה הוא אומר? \u0003קדירה בת יומא נמי\u0004 \u0005[גם כן]\u0006 \u0003אי אפשר\u0004 ש\u0003לא פגמה פורתא\u0004 \u0005[תיפגם מעט]\u0006 מאז שנתבשלה, ובכל זאת אסרה אותה התורה.","ושואלים: \u0003ור' שמעון,\u0004 שסבור שנותן טעם לפגם מותר, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 לשיטתו? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 נאמר: \u0003\"לא תאכלו כל נבלה לגר אשר בשעריך\u0004 תתננה ואכלה\" (דברים יד, כא), ומכאן הוא למד כך: \u0003כל הראויה לגר\u0004 שאפשר לאכול אותה — הרי \u0003קרויה נבילה\u0004 ואסורה,"],["\u0003שאין ראויה לגר,\u0004 כגון שהתקלקלה והסריחה ואינה ראויה לאכילה — \u0003אינה קרויה נבלה\u0004 לענין איסור.","\u0003ור' מאיר,\u0004 מה הוא משיב על כך? הוא סבור: \u0003ההוא\u0004 אותו פסוק בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 זו שהיתה \u0003סרוחה מעיקרא\u0004 \u0005[מתחילתה],\u0006 שגם בחייה לא היתה ראויה לאכילה, מפני שהיה בה פגם מאוס, ומתחילתה לא היתה אסורה כנבילה. אבל זאת שמתחילתה היתה אסורה — אוסרת גם כשטעמה פגום. \u0003ור' שמעון,\u0004 מה הוא משיב על כך? \u0003סרוחה מעיקרא\u0004 \u0005[מתחילתה]\u0006 \u0003לא צריכא מיעוטא\u0004 \u0005[אינה צריכה מיעוט\u0006 מהמקרא\u0005],\u0006 כי \u0003עפרא בעלמא\u0004 \u0005[עפר סתם]\u0006 \u0003הוא,\u0004 ואין עליה כלל שם נבילה.","\u0003אמר עולא: מחלוקת\u0004 זו של ר' מאיר ור' שמעון, היא באיסור \u0003שהשביח\u0004 בתחילה כשנפל לתבשיל \u0003ולבסוף פגם,\u0004 שבזה ר' מאיר אוסר, מאחר שנתן בתחילה טעם לשבח. \u0003אבל\u0004 איסור ש\u0003פגם מעיקרא\u0004 \u0005[מתחילה]\u0006 כשנפל להיתר \u0003דברי הכל מותר.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב חגא לעולא\u0004 ממה ששנינו בברייתא: \u0003יין שנפל לתוך עדשים, וחומץ שנפל לתוך גריסין\u0004 — \u0003אסור, ור' שמעון מתיר. והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003פגם מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003הוא, ופליגי\u0004 \u0005[ונחלקו\u0006 בכך\u0005]!\u0006","\u0003אמר עולא:\u0004 רב \u0003חגא\u0004 שהקשה את הקושיה, \u0003לא מידע ידע מאי קאמרי רבנן\u0004 \u0005[אינו יודע מה אומרים חכמים],\u0006 \u0003תיובתא קא מותיב\u0004 \u0005[קושיות\u0006 \u0005הוא מקשה]?\u0006 \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון שנפל לתוך גריסין צוננין והרתיחם,\u0004 ובמקרה זה \u0003נעשה כמי שהשביח\u0004 מתחילה, שחומץ משבח טעמם של גריסין צוננים, \u0003ולבסוף פגם\u0004 כאשר הרתיחם, \u0003ו\u0004אז הוא \u0003אסור\u0004 לדברי ר' מאיר.","\u0003ו\u0004בניגוד לדברי עולא, \u0003ר' יוחנן אמר: בפוגם מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003מחלוקת.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 בבירור דברי ר' יוחנן: \u0003בפוגם מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003מחלוקת\u0004 זו של ר' מאיר ור' שמעון, \u0003אבל\u0004 אם \u0003השביח ולבסוף פגם\u0004 — \u0003דברי הכל אסור, או דלמא\u0004 \u0005[שמא]\u0006 \u0003בין בזו ובין בזו מחלוקת?\u0004 שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003אמר רב עמרם: אפשר\u0004 (האם ייתכן) \u0003איתא להא\u0004 \u0005[\u0006ש\u0005ישנה לזו\u0006 שאמר\u0005]\u0006 \u0003ר' יוחנן\u0004 שנחלקו בפוגם מעיקרו, \u0003ולא תניא לה במתניתין\u0004 \u0005[ואינה שנויה במשנה]?\u0006","\u0003נפק דק ואשכח\u0004 \u0005[יצא\u0006 מבית המדרש ו\u0005דקדק\u0006 במשנה \u0005ומצא],\u0006 \u0003דתניא\u0004 \u0005[ששנויה]\u0006 משנה: \u0003שאור של חולין שנפל לתוך העיסה ויש בו כדי להחמיץ ו\u0004אכן \u0003החמיצה, ואחר כך נפל\u0004 לתוך עיסה זו \u0003שאור של תרומה או שאור של כלאי הכרם ו\u0004גם הוא \u0003יש בו כדי להחמיץ\u0004 — הרי זה \u0003אסור,\u0004 משום שאומרים שהשאור של האיסור הוסיף בהחמצה. \u0003ור' שמעון מתיר,\u0004 משום שהשאור הנוסף רק פוגם בעיסה שהוחמצה כבר.","\u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003פגם מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003הוא, ופליגי\u0004 \u0005[ו\u0006בכל זאת \u0005חולקים\u0006 הם\u0005]\u0006 שסתם משנה דעת ר' מאיר היא.","\u0003אמר ר' זירא:\u0004 יש לדחות, \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003עיסה,\u0004 שאף על פי שטעמה נפגם על ידי השאור הנוסף, מכל מקום מושבחת היא בכך \u0003הואיל וראויה לחמע\u0004 (להחמיץ) \u0003בה כמה עיסות אחרות,\u0004 שככל שהיא מוחמצת יותר — הרי זה משביח אותה לצורך זה ואין זה נחשב כפוגם מתחילה.","ומציעים עוד מקור לדברי ר' יוחנן: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003שאור של תרומה ושל חולין שנפלו לתוך העיסה,\u0004 היה \u0003בזה\u0004 עצמו \u0003כדי להחמיץ\u0004 את העיסה \u0003ובזה\u0004 בלבד \u0003כדי להחמיץ, וחימצו\u0004 שניהם יחד — \u0003אסור,\u0004 משום שיש בעיסה תערובת של חימוץ אסור, ו\u0003ר' שמעון מתיר.\u0004 אם \u0003נפל\u0004 שאור \u0003של תרומה תחלה\u0004 — \u0003דברי הכל אסור. נפל של חולין ואחר כך נפל של תרומה או של כלאי הכרם\u0004 — אף זה \u0003אסור, ור' שמעון מתיר.\u0004","\u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 במקרה האחרון ש\u0003פגם\u0004 האיסור \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003ופליגי\u0004 \u0005[ו\u0006בכל זאת \u0005נחלקו\u0006 בכך\u0005]\u0006 ר' מאיר ור' שמעון! \u0003וכי תימא, הכא נמי\u0004 \u0005[ואם\u0006 \u0005תאמר, כאן גם כן]\u0006 יש להסביר"],["\u0003ר' זירא,\u0004 שהחמצה יתירה של העיסה הריהי משביחה אותה, משום שניתן להשתמש בה לחמץ עיסות אחרות, \u0003תא שמע מסיפא\u0004 \u0005[בוא\u0006 ו\u0005שמע\u0006 ראיה \u0005מסופה\u0006 של אותה ברייתא\u0005]:\u0006 \u0003היין\u0004 \u0003שנפל לתוך עדשים, וחומץ שנפל לתוך גריסין\u0004 — \u0003אסור, ור' שמעון מתיר. והא הכא נמי\u0004 \u0005[והרי כאן גם כן]\u0006 ש\u0003פגם מעיקרא\u0004 \u0005[מתחילה],\u0006 \u0003ופליגי\u0004 \u0005[ונחלקו]!\u0006","\u0003וכי תימא, הכא נמי כדשני ליה\u0004 \u0005[ואם תאמר, כאן גם כן\u0006 מדובר \u0005כמו שתירץ לו]\u0006 \u0003עולא לר' חגא:\u0004 במקרה \u0003כשהשביח ולבסוף פגם\u0004 כשנפל לצוננין והרתיחם — אין אפשרות לומר כך, \u0003ומי פליגי\u0004 \u0005[והאם חלוקים\u0006 הם\u0005]\u0006 במקרה \u0003שהשביח ולבסוף פגם? והא קתני\u0004 \u0005[והרי שנינו]:\u0006 \u0003נפל של תרומה תחלה\u0004 — \u0003דברי הכל אסור,\u0004 מאחר שהשביח בתחילה על ידי התרומה, אף שלבסוף פגם השאור של החולין!","\u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 ש\u0003בפגם מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003מחלוקת,\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","ושואלים: \u0003הני תלתא בבי דקתני\u0004 \u0005[אותן שלוש פסקאות ששנה\u0006 בברייתא\u0005]\u0006 במקרים שונים, \u0003למה לי\u0004 את שלושתן? \u0003בשלמא בבא דסיפא\u0004 \u0005[נניח\u0006 ב\u0005פסקה האחרונה]\u0006 ביין שנפל לתוך עדשים, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]:\u0006 \u0003בפוגם מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003מחלוקת\u0004 כפי שהוכחנו, \u0003מציעתא נמי\u0004 \u0005[\u0006בפסקה \u0005האמצעית גם כן]\u0006 שנפל שאור של תרומה תחילה, משמיע לנו כי \u0003השביח ולבסוף פגם\u0004 — \u0003דברי הכל אסור,\u0004","\u0003אלא רישא\u0004 \u0005[\u0006בפסקה \u0005הראשונה]\u0006 בנפלו תרומה וחולין בבת אחת \u0003למה לי\u0004 להביאה כלל? שהרי אפשר היה ללמוד מן ההמשך ובאופן זה: \u0003השתא, ומה סיפא דלא קא משבח כלל, אסרי רבנן\u0004 \u0005[עכשיו, ומה בסוף\u0006 במקרה שנפל היין לעדשים, \u0005שאינו משביח כלל,\u0006 בכל זאת \u0005אוסרים חכמים],\u0006 \u0003רישא דקא משבח מיבעיא\u0004 \u0005[\u0006במקרה \u0005הראשון שהוא משביח\u0006 בתחילה \u0005צריך\u0006 לומר\u0005]\u0006 שאוסרים?","\u0003אמר אביי: רישא\u0004 \u0005[ה\u0006פסקה \u0005הראשונה]\u0006 \u0003לר' שמעון אצטריך\u0004 \u0005[הוצרכה]\u0006 להשמיע לנו שגם בזה הוא מתיר. \u0003והכי קאמרי ליה רבנן\u0004 \u0005[וכך אמרו לו חכמים]\u0006 \u0003לר' שמעון: עיסה זו ראויה להחמיץ בשתי שעות\u0004 אם היה נופל שם רק שאור של היתר, \u0003מי גרם לה\u0004 שבח זה \u0003שתחמיץ בשעה אחת?\u0004 שאור של \u0003איסור.\u0004 ואם כן, אף אתה צריך להודות לנו שהוא משביח ולבסוף פוגם!","\u0003ור' שמעון\u0004 מה ענה הוא על כך? \u0003כשהשביחו\u0004 — \u0003שניהם השביחו,\u0004 ולא רק האיסור לבדו, \u0003כשפגמו\u0004 — \u0003שניהם פגמו.\u0004","ושואלים: אף \u0003ל\u0004דעת \u0003ר' שמעון, ליצטרף\u0004 \u0005[שיצטרפו]\u0006 \u0003היתר ואיסור בהדי הדדי וליתסר\u0004 \u0005[זה עם זה, ושייאסר],\u0006 שהרי גם ר' שמעון מודה שאם השביח מתחילה — אסור!","ומשיבים: \u0003ר' שמעון לטעמיה\u0004 \u0005[לשיטתו],\u0006 ש\u0003אמר: אפילו איסור ואיסור נמי לא מיצטרפי\u0004 \u0005[גם כן אינם מצטרפים]\u0006 לאסור, וכל שכן איסור והיתר,","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הערלה וכלאי הכרם\u0004 שנפלו בתוך היתר, ואין בכל אחד מהם כדי לאוסרו — \u0003מצטרפין\u0004 אם יש בשניהם יחד כשיעור לאסור, \u0003ר' שמעון אומר: אין מצטרפין,\u0004 וכל איסור נידון לעצמו. וגם כאן, הואיל ובשעה הראשונה שהשביח האיסור — לא יכול היה להשביח בעצמו — אין ההיתר מצטרף אליו לאסור.","מסופר, \u0003ההוא עכברא\u0004 \u0005[עכבר אחד]\u0006 ש\u0003נפל לחביתא דשיכרא\u0004 \u0005[לחבית שיכר],\u0006 \u0003אסריה\u0004 \u0005[אסר]\u0006 \u0003רב לההוא שיכרא\u0004 \u0005[את השיכר ההוא].\u0006 \u0003אמרוה רבנן קמיה\u0004 \u0005[חכמים לפני]\u0006 \u0003רב ששת:\u0004 \u0003נימא קסבר\u0004 \u0005[האם נאמר\u0006 ש\u0005הוא סבור]\u0006 ש\u0003נותן טעם לפגם אסור?\u0004 שהרי העכבר טעמו בוודאי פוגם!","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ששת: בעלמא סבר\u0004 \u0005[בכלל סבור]\u0006 \u0003רב\u0004 ש\u0003נותן טעם לפגם מותר, והכא\u0004 \u0005[וכאן]\u0006 \u0003חידוש\u0004 מיוחד \u0003הוא\u0004 שחידשה התורה בעכבר וכיוצא בו, \u0003דהא מימאס מאיס ובדילי אינשי מיניה\u0004 \u0005[שהרי מאוס\u0006 הוא \u0005ואנשים בדלים ממנו\u0006 מעצמם\u0005],\u0006 \u0003ואפילו הכי אסריה רחמנא\u0004 \u0005[כך אסרה אותו התורה],\u0006 \u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003נותן טעם לפגם נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור\u0004 בו, שלא כמו שלמדנו מנבילה.","\u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרב ששת: אלא מעתה,\u0004 לפי הסברך זה, שחידוש הוא, ובא להחמיר יותר משאר איסורים. \u0003ליטמא\u0004 \u0005[שיטמא]\u0006 העכבר וכיוצא בו כשהוא \u0003לח ו\u0004גם כשהוא \u0003יבש, אלמה תנן\u0004 \u0005[מדוע שנינו\u0006 במשנה\u0005]:\u0006 השרצים \u0003מטמאין\u0004 כשהם \u0003לחים ואין מטמאין יבשים?\u0004","אמר להם: \u0003ולטעמיך\u0004 \u0005[ולשיטתך]\u0006 שאתם מדמים דין טומאה לדין איסור, \u0003שכבת זרע\u0004 שגם היא מאוסה גם כן \u0003תטמא לח ויבש, אלמה תנן\u0004 \u0005[מדוע שנינו\u0006 במשנה\u0005]:\u0006 בשכבת זרע ושרץ \u0003מטמאין לחין ואין מטמאין יבשין?\u0004","\u0003אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]?\u0006 \u0003\"שכבת זרע\" אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 כלומר, גזירת הכתוב היא שהיא מטמאה רק כשהיא לחה, כאשר היא \u0003ראויה להזריע, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין עכבר וכיוצא בו — \u0003\"במתם\"\u0004 (\"וכל אשר יפול עליו מהם במותם יטמא\" ויקרא יא, לב) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 — שהם מטמאים רק \u0003כעין מותם,\u0004 כמו שהיו בזמן מותם, ולכן כשהם יבשים אינם מטמאים עוד. ואין מכאן סתירה לדברי שחידוש הוא ויש לאוסרו אף כשנותן טעם לפגם.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך],\u0006 על עצם הסברה שהעלנו, \u0003רב שימי מנהרדעא: ומי מאיס\u0004 \u0005[והאם\u0006 העכבר הוא \u0005מאוס]?\u0006 \u0003והלא עולה על שלחן של מלכים,\u0004 שנחשב להם כמאכל מובחר! \u0003אמר רב שימי מנהרדעא, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא בדדברא\u0004 \u0005[זה ב\u0006עכבר \u0005של שדה]\u0006 שהוא עולה על שולחן מלכים, \u0003הא בדמתא\u0004 \u0005[זה ב\u0006עכבר \u0005של עיר]\u0006 שהוא מאוס לכל.","\u0003אמר רבא: הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003נותן טעם לפגם\u0004 — \u0003מותר, ועכברא בשיכרא לא ידענא מאי טעמא\u0004 \u0005[ועכבר בשיכר אין אני יודע מה הטעם]\u0006 של \u0003רב\u0004 שאסר, \u0003אי\u0004 \u0005[האם]\u0006 \u0003משום דקסבר\u0004 \u0005[שהוא סבור]\u0006 בכלל: \u0003נותן טעם לפגם אסור, ולית הלכתא כוותיה\u0004 \u0005[ואין הלכה כמותו],\u0006 \u0003אי\u0004 \u0005[או]\u0006 \u0003משום דקסבר\u0004 \u0005[שהוא סבור]\u0006 שבכלל \u0003נותן טעם לפגם\u0004 — \u0003מותר,\u0004 אלא \u0003עכברא בשיכרא אשבוחי משבח\u0004 \u0005[עכבר בשיכר\u0006 הוא \u0005משביח את\u0006 טעמו\u0005],\u0006 ולכן הוא אסור.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006"],["\u0003נפל\u0004 עכבר \u0003לגו חלא\u0004 \u0005[לתוך חומץ],\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 דינו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הילל לרב אשי: הוה עובדא בי\u0004 \u0005[היה מעשה\u0006 כעין זה \u0005בביתו]\u0006 של \u0003רב כהנא, ואסר\u0004 אותו \u0003רב כהנא,\u0004 ומכאן שהוא נותן טעם לשבח ופוסל. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: משם אין ראיה, \u0003ההוא אימרטוטי אימרטט\u0004 \u0005[אותו\u0006 עכבר \u0005נתמרטט\u0006 לחתיכות קטנות\u0005]\u0006 ורב כהנא אסר משום החשש שיבואו לאכול חתיכה ממש מן העכבר בתוך החומץ.","מסופר, \u0003רבינא סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 \u0003לשעורי\u0004 \u0005[לשער אותו]\u0006 ולבטלו \u0003במאה וחד\u0004 \u0005[ואחד],\u0006 \u0003אמר: לא גרע\u0004 \u0005[גרוע],\u0006 אינו חמור יותר \u0003מתרומה, דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003תרומה עולה\u0004 (מתבטלת) \u0003באחד ומאה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב תחליפא בר גיזא לרבינא: דלמא\u0004 \u0005[שמא]\u0006 \u0003כתבלין של תרומה בקדירה דמי\u0004 \u0005[נחשב],\u0006 ש\u0003לא בטיל טעמייהו\u0004 \u0005[בטל טעמם]\u0006 באחד ומאה, אלא ביותר מכך!","ועוד מסופר, \u0003רב אחאי שיער בחלא בחמשין\u0004 \u0005[בחומץ בחמישים]\u0006 שסבור היה שחומץ שטעמו חריף אינו זקוק לשישים כמו שאר איסורים שבתורה כדי לבטל טעמו של העכבר. \u0003ורב שמואל בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא שיער בשיכרא בשיתין\u0004 \u0005[בשיכר בשישים].\u0006","ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא: \u0003אידי ואידי בשיתין\u0004 \u0005[זה וזה\u0006 בטלים \u0005בשישים],\u0006 \u0003וכן כל איסורין שבתורה,\u0004 בדרך כלל בטלים בשישים.","\u0003נכרי שהיה מעביר עם ישראל כדי יין ממקום למקום, אם היה בחזקת המשתמר\u0004 — \u0003מותר, אם הודיעו\u0004 הישראל לנכרי \u0003שהוא מפליג\u0004 (הולך למקום רחוק), הרי שיעור הזמן בו נאסר היין, אם לא היה שם ישראל — \u0003כדי שישתום\u0004 שיעשה נקב במגופת החבית (פקק העשוי מטיט וכיוצא בו), \u0003ויסתום\u0004 אחר כך את הנקב, \u0003ויגוב\u0004 ויתייבש המקום שבו עשה את הנקב. \u0003רבן שמעון בן גמליאל אומר: כדי שיפתח את החבית\u0004 על ידי שבירת המגופה כולה, \u0003ויגוף\u0004 ויעשה לה מגופה חדשה, \u0003ותיגוב\u0004 (ותתייבש) המגופה הזו.","\u0003המניח יינו בקרון או בספינה, והלך לו בקפנדריא\u0004 (בדרך קצרה) והנכרי אינו יודע מתי הישראל חוזר, אפילו אם \u0003נכנס\u0004 בינתיים \u0003למדינה\u0004 (לעיר) \u0003ורחץ\u0004 — הרי זה \u0003מותר,\u0004 משום שהגוי לא ינסך, שהוא מפחד שמא יגיע הישראל בכל רגע.","\u0003אם הודיעו\u0004 הישראל לנכרי \u0003שהוא מפליג\u0004 לזמן מרובה — הרי הזמן שמותר הוא עד \u0003כדי שישתום\u0004 (יעשה נקב) \u0003ויסתום ויגוב. רבן שמעון בן גמליאל אומר: כדי שיפתח את החבית ויגוף\u0004 המגופה \u0003ותיגוב\u0004 המגופה.","ישראל \u0003המניח נכרי\u0004 לבדו \u0003בחנות\u0004 יין שלו, \u0003אף על פי שיצא ונכנס\u0004 הישראל ואינו נמצא שם כל הזמן — \u0003מותר, ואם הודיעו שהוא מפליג\u0004 — \u0003כדי שישתום ויסתום ויגוב. רבן שמעון בן גמליאל אומר: כדי שיפתח את החבית ויגוף ותיגוב.\u0004","\u0003היה\u0004 ישראל \u0003אוכל עמו\u0004 עם הנכרי \u0003על השולחן, והניח לגינין\u0004 (כדים קטנים) של יין \u0003על השולחן, ולגין\u0004 אחר \u0003על הדולבקי\u0004 (דלפק, שמניחים עליו כלי אוכל ושתיה) \u0003והניחו\u0004 לבדו \u0003ויצא\u0004 — \u0003מה שעל השולחן אסור,\u0004 שמן הסתם לקח ושתה ממנו, ואילו הלגין \u0003שעל הדולבקי\u0004 — \u0003מותר. ואם אמר לו\u0004 לגוי: \u0003הוי מוזג ושותה\u0004 — \u0003אף\u0004 הלגין \u0003שעל הדולבקי אסור,\u0004 שהרי התיר לו למזוג לעצמו. וכן \u0003חביות פתוחות\u0004 שהיו שם — \u0003אסורות, סתומות\u0004 — \u0003מותרות,\u0004 אם שהה מחוץ למקום \u0003כדי שיפתח ויגוף ותיגוב.\u0004","בפירוש המשנה מבררים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003\"בחזקת המשתמר\"?\u0004 ומסבירים: \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיו חמריו ופועליו,\u0004 שהיו עמי ארצות וחזקתם טמאים, \u0003טעונין טהרות\u0004 (יין או פירות שנעשו בטהרה), והוא מזהירם שלא יגעו בהם, אבל אינו יודע אם עשו כן או לא, \u0003אפילו הפליג מהן יותר ממיל\u0004 — \u0003טהרותיו טהורות,\u0004 שאנו אומרים שכיון שהזהירם הם חוששים ממנו. \u0003ואם אמר להן: \"לכו ואני בא אחריכם\",\u0004 שידעו שאינו הולך עימם, הרי \u0003כיון שנתעלמה עינו מהם\u0004 ואין הוא עוד רואה אותם — \u0003טהרותיו טמאות.\u0004","ושואלים: \u0003מאי שנא רישא\u0004 \u0005[במה שונה\u0006 בתחילה \u0005הראש,\u0006 במקרה הראשון\u0005]\u0006 שאם הפליג — טהרותיו טהורות, \u0003ומאי שנא סיפא\u0004 \u0005[ובמה שונה הסוף]\u0006 שלאחר שנעלמו מעיניו — טמאות? \u0003אמר רב יצחק: רישא\u0004 \u0005[בתחילה]\u0006 מדובר \u0003במטהר חמריו ופועליו לכך,\u0004 כלומר שדואג שיטבלו, כדי שלא יטמאו את הטהרות, ולכן אין לחשוש למגעם.","ומקשים: \u0003אי הכי, סיפא נמי\u0004 \u0005[אם כך, בסוף גם כן]\u0006 כיון שטיהר אותם לכך, מדוע אנו צריכים לחשוש שטימאו אותם? ומשיבים: \u0003אין עם הארץ מקפיד על מגע חבירו\u0004 ואף על פי שהם עצמם היו טהורים, שמא פגעו בדרך בעם הארץ אחר ונטמאו הטהרות על ידו, ובזה אין הם מקפידים. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אם לכך אתה חושש, \u0003אפילו רישא נמי נימא הכי\u0004 \u0005[בתחילה גם כן נאמר כך]!\u0006","\u0003אמר רבא:\u0004"],["\u0003בבא להם\u0004 ב\u0003דרך עקלתון\u0004 (מתפתלת) שהוא יכול לבוא בדרך עקומה, מסביב, באופן שהם אינם יכולים לדעת מהיכן הוא בא, ולכן הם מתייראים. ומשיבים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שבאופן כזה מדובר, \u0003סיפא נמי\u0004 \u0005[בסוף גם כן]\u0006 מדוע לא נאמר שהם מתייראים? ומשיבים: \u0003כיון\u0004 ש\u0003אמר להם \"לכו ואני בא אחריכם\", סמכא דעתייהו\u0004 \u0005[סומכת דעתם]\u0006 שלא יפתיע אותם.","שנינו במשנה כמה דינים דומים: \u0003המניח נכרי בחנותו כו' המניח יינו בקרון או בספינה כו'.\u0004 ומעירים: \u0003וצריכא\u0004 \u0005[ונצרכה\u0006 לומר\u0005]\u0006 משנה זו על כל המקרים המתוארים בה, אף שלכאורה כולם עניינם דומה, \u0003דאי תנא\u0004 \u0005[שאם\u0006 היה \u0005שונה]\u0006 רק במקרה של \u0003נכרי\u0004 המעביר חביות היינו אומרים: שם אין חוששים, כיון \u0003דסבר\u0004 \u0005[ש\u0006הגוי \u0005סבור]:\u0006 \u0003דלמא אתי וחזי ליה\u0004 \u0005[שמא יבוא\u0006 בעל הבית \u0005ויראה אותו],\u0006 \u0003אבל בקרון או בספינה\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003מפליג לה לספינתיה ועביד מאי דבעי\u0004 \u0005[שמרחיק את ספינתו ועושה מה שרוצה]\u0006 באופן שאין הישראל יכול לראות אותו.","\u0003ואי תנא\u0004 \u0005[ואם היה שונה]\u0006 \u0003בקרון או בספינה,\u0004 היינו אומרים: שם הוא חושש \u0003משום דסבר\u0004 \u0005[שסבור]:\u0006 \u0003דלמא אתי באורחא אחריתי וקאי אגודא וחזי לי\u0004 \u0005[שמא\u0006 הישראל \u0005בא בדרך אחרת ועומד על גדת הנהר ורואה אותי],\u0006 \u0003אבל נכרי בחנותו אימא אחיד לה לבבא ועביד כל דבעי\u0004 \u0005[אמור\u0006 ש\u0005אוחז,\u0006 סוגר, \u0005את הדלת ועושה מה ש\u0006הוא \u0005רוצה]\u0006 ואינו חושש שמא יראוהו, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שבכל המקרים הדין שווה, ואין לחשוש לכך אם לא הודיעו שמפליג.","על המחלוקת במשנה מהו פרק הזמן שבו נאסר היין אם הודיעו שהוא מפליג, \u0003אמר רבה בר בר חנה אמר ר' יוחנן: מחלוקת\u0004 זו אם הוא זמן של עשיית נקב במגופת החבית וסתימתו עד שיתייבש (כדעת חכמים), או זמן ארוך יותר של פתיחת המגופה ועשיית מגופה חדשה עד שתתייבש (כדעת רבן שמעון בן גמליאל), היא רק במגופה \u0003של סיד,\u0004 שאין סתימה של חור ניכרת בה, \u0003אבל בשל טיט\u0004 שסתימה חדשה ניכרת בה — \u0003דברי הכל\u0004 אין היין נאסר אלא עד \u0003כדי שיפתח ויגוף ויגוב.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על סברה זו ממה ששנינו בברייתא, ש\u0003אמר רבן שמעון בן גמליאל לחכמים: והלא סתומו\u0004 (סתימתו) של הנקב \u0003ניכר בין מלמעלה ובין מלמטה,\u0004 והגוי ירא לעשות זאת.","ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 גם \u0003בשל טיט מחלוקת, היינו דקתני\u0004 \u0005[זהו ששנינו\u0006 שטוען רבן שמעון בן גמליאל\u0005]:\u0006 \u0003סתומו ניכר בין מלמעלה ובין מלמטה, אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003בשל סיד מחלוקת, בשלמא\u0004 \u0005[נניח]\u0006 \u0003למטה ידיע\u0004 \u0005[ידוע]\u0006 המקום שסתם, לפי שאינו יכול למלא בסיד את כל החור, ונשאר חלל למטה, \u0003אלא למעלה הא לא ידיע\u0004 \u0005[הרי אינו ידוע]\u0006 כשסותמו בסיד!","ומשיבים: \u0003רבן שמעון בן גמליאל הוא\u0004 ש\u0003לא ידע\u0004 ולא היה בטוח \u0003מאי קאמרי רבנן\u0004 \u0005[מה אומרים,\u0006 במה מדברים, \u0005חכמים],\u0006 \u0003והכי קאמר להו\u0004 \u0005[וכך אמר להם]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003ב\u0004סתימה \u0003של טיט קאמריתו\u0004 \u0005[אתם אומרים],\u0006 הרי בזה \u0003סתומו ניכר בין מלמעלה ובין מלמטה, ואי\u0004 \u0005[ואם]\u0006 \u0003בשל סיד קאמריתו\u0004 \u0005[אומרים אתם],\u0006 \u0003נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003למעלה לא ידיע\u0004 \u0005[ידוע],\u0006 \u0003למטה מיהא ידיע\u0004 \u0005[על כל פנים ידוע]!\u0006 \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם משיבים לטענה זו? הם סבורים כי \u0003כיון\u0004 ש\u0003מלמעלה לא ידיע\u0004 \u0005[ידוע]\u0006 שהיה שם נקב, \u0003לא מסיק אדעתיה דאפיך וחזי ליה\u0004 \u0005[מעלה\u0006 הגוי \u0005על דעתו ש\u0006הישראל \u0005יהפוך ויראה אותו].\u0006 \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003זימנין דחלים\u0004 \u0005[פעמים שמתרפא\u0006 ומתמלא הנקב\u0005]\u0006 ואי אפשר לדעת שעשאו.","\u0003אמר רבא: הלכה כרבן שמעון בן גמליאל, הואיל ותנן סתמא כוותיה\u0004 \u0005[ושנינו\u0006 במשנה \u0005סתם כשיטתו].\u0006","\u0003דתנן\u0004 \u0005[ששנינו\u0006 בסוף המשנה\u0005]:\u0006 \u0003היה אוכל על השולחן\u0004 \u0003עמו, והניח לגין על השולחן, לגין על הדולבקי והניח ויצא\u0004 — \u0003מה שעל השולחן\u0004 הוא \u0003אסור, מה שעל הדולבקי מותר, ואם אמר לו: \"הוי מזוג ושותה\"\u0004 — \u0003אף שעל הדולבקי אסור. חביות פתוחות\u0004 — \u0003אסורות, סתומות\u0004 — \u0003מותרות, כדי שיפתח ויגוף ותיגוב.\u0004 אם כן, פסקה המשנה במפורש שהשיעור הוא כדי שיפתח ויגוף.","ואומרים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הוא\u0005],\u0006 הרי הדבר נאמר במפורש במשנה! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 את הפסקה הזו \u0003כולה\u0004 \u0003רבן שמעון בן גמליאל קתני לה\u0004 \u0005[שנה אותה]\u0006 והיא עדיין המשך דבריו הקודמים, ולא דברי סתם משנה, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 רבא שאין הדבר כן.","ושואלים: \u0003וכי מאחר דקיימא לן כוותיה\u0004 \u0005[מאחר שמוחזק לנו כשיטתו]\u0006 של \u0003רבן שמעון בן גמליאל דלא חייש לשתומא\u0004 \u0005[שאינו חושש לעשיית נקב\u0006 בחבית\u0005],\u0006 \u0003ו\u0004מצד אחר אף לדברי רבן שמעון בן גמליאל, שחושש לפתיחה והחזרה של המגופה, אין אנו חוששים, שהרי אנו אומרים כי \u0003הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003ר' אליעזר דלא חייש לזיופא\u0004 \u0005[שאינו חושש לזיוף],\u0006 שבמקום שיש טרחה יתירה, כגון ביצירת מגופה חדשה, אין חוששים שיבוא הגוי לזייף, \u0003האידנא מאי טעמא לא מותבינן חמרא\u0004 \u0005[בזמן הזה מה טעם אין אנו משאירים יין]\u0006 שבחביות סתומות \u0003ביד גוים?\u0004 ומשיבים: \u0003משום\u0004 שיש בהן \u0003שייכא\u0004 \u0005[הנקב הקטן\u0006 שבמגופת החבית\u0005]\u0006 ואנו חוששים שהגוי ירחיבנו קצת וישתה ממנו.","\u0003אמר רבא: זונה גויה, וישראל מסובין אצלה\u0004 — \u0003חמרא שרי\u0004 \u0005[היין\u0006 שנמצא שם \u0005מותר],\u0006 \u0003נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003תקיף\u0004 (חזק) \u0003להו יצרא\u0004 \u0005[להם\u0006 \u0005יצר]\u0006 ה\u0003עבירה\u0004 של זנות, ולכן הם נמצאים אצלה,"],["— \u0003יצרא\u0004 \u0005[היצר]\u0006 של \u0003יין נסך לא תקיף להו\u0004 \u0005[אינו חזק אצלם]\u0006 ולא יניחו לה לנסך. אבל אם היתה \u0003זונה ישראלית וגוים מסובין\u0004 אצלה — \u0003חמרא\u0004 \u0005[היין]\u0006 \u0003אסור, מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003הואיל וזילה עלייהו\u0004 \u0005[ו\u0006היא \u0005מזולזלת בעיניהם],\u0006 \u0003בתרייהו גרירא\u0004 \u0005[אחריהם\u0006 היא \u0005נגררת],\u0006 והם מנסכים את היין כרצונם בלי להתחשב בה.","והגמרא מביאה סדרת מעשים הנוגעים לדינים שבמשנתנו. מסופר, \u0003ההוא ביתא דהוה יתיב ביה חמרא\u0004 \u0005[בית אחד שהיה מונח בו יין]\u0006 של \u0003ישראל, על\u0004 \u0005[נכנס]\u0006 לשם \u0003גוי, אחדה לדשא באפיה\u0004 \u0005[\u0006ו\u0005אחז,\u0006 סגר \u0005את הדלת בפניו]\u0006 של הישראל, \u0003ו\u0004אולם \u0003הוה ביזעא בדשא\u0004 \u0005[היה סדק בדלת],\u0006 \u0003אישתכח גוי דקאי ביני דני\u0004 \u0005[נמצא גוי ש\u0006היה \u0005עומד בין החביות].\u0006 \u0003אמר רבא: כל\u0004 מה \u0003דלהדי ביזעא\u0004 \u0005[ש\u0006נמצא \u0005כנגד הסדק]\u0006 שניתן לראות דרכו את הגוי — \u0003שרי\u0004 \u0005[מותר],\u0006 משום שמתיירא הוא לגעת ביין, שמא יראוהו. \u0003דהאי גיסא והאי גיסא\u0004 \u0005[\u0006ואילו כל שנמצא \u0005שבצד זה ובצד זה],\u0006 שלא ניתן לראותו דרך הסדק — \u0003אסור,\u0004 שמא נסכו הגוי.","עוד מסופר, \u0003ההוא חמרא\u0004 \u0005[יין]\u0006 של \u0003ישראל דהוה יתיב בביתא\u0004 \u0005[שהיה מונח בבית],\u0006 בקומה התחתונה, \u0003דהוה דייר\u0004 \u0005[שהיה גר]\u0006 בו \u0003ישראל ב\u0004קומה ה\u0003עליונה ו\u0004ה\u0003גוי בתחתונה,\u0004 וניתן לראות את היין מן הקומה העליונה. \u0003שמעו קל תיגרא\u0004 \u0005[קול מריבה],\u0006 \u0003נפקי\u0004 \u0005[ויצאו\u0006 שניהם\u0005],\u0006 \u0003קדים אתא גוי אחדה לדשא באפיה\u0004 \u0005[קדם\u0006 ו\u0005בא\u0006 \u0005הגוי\u0006 לבית ו\u0005אחז,\u0006 סגר \u0005את הדלת בפניו]\u0006 של הישראל. \u0003אמר רבא: חמרא שרי\u0004 \u0005[היין מותר],\u0006 והסברה שבדבר: \u0003מימר\u0004 \u0005[אמור]\u0006 \u0003אמר\u0004 הגוי בליבו: \u0003כי היכי דקדים אתאי אנא\u0004 \u0005[כמו שקדמתי, ובאתי אני],\u0006 \u0003קדים ואתא\u0004 \u0005[קדם ובא]\u0006 שכני ה\u0003ישראל\u0004 לבית, \u0003ויתיב\u0004 \u0005[ו\u0006הוא \u0005יושב]\u0006 \u0003ב\u0004קומה ה\u0003עליונה וקא חזי לי\u0004 \u0005[ורואה אותי],\u0006 ולא ניסך.","עוד מסופר, \u0003ההוא אושפיזא דהוה יתיב ביה חמרא\u0004 \u0005[בית מלון אחד שהיה מונח בו יין]\u0006 של \u0003ישראל, אישתכח\u0004 \u0005[נמצא\u0006 שם\u0005]\u0006 \u0003גוי דהוה יתיב בי דני\u0004 \u0005[שהיה יושב בין החביות\u0006 של היין\u0005].\u0006 \u0003אמר רבא: אם\u0004 הגוי \u0003נתפס עליו\u0004 על יין זה \u0003כגנב\u0004 כשמוצאים אותו שם — \u0003שרי\u0004 \u0005[מותר]\u0006 היין, כי מחמת יראתו שמא יתפסוהו שם אין לו פנאי לנסך, ואין לחשוש שנגע, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 נתפס עליו כגנב — \u0003אסיר\u0004 \u0005[אסור].\u0006","\u0003ההוא ביתא דהוה יתיב ביה חמרא\u0004 \u0005[בית אחד שהיה מונח בו יין],\u0006 \u0003אישתכח\u0004 \u0005[נמצא]\u0006 \u0003גוי דהוה קאים בי דני\u0004 \u0005[שהיה עומד בין החביות].\u0006 \u0003אמר רבא: אי אית ליה לאישתמוטי\u0004 \u0005[אם יש לו\u0006 דרך לגוי \u0005להשתמט]\u0006 ולהסביר את כניסתו לשם — \u0003חמרא אסיר\u0004 \u0005[היין אסור],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003חמרא שרי\u0004 \u0005[היין מותר].\u0006 \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003ננעל הפונדק, או שאמר לו\u0004 היהודי לגוי: \u0003\"שמור\u0004 את ייני\" — היין \u0003אסור. מאי לאו אף על גב דלית ליה לאישתמוטי\u0004 \u0005[האם לא\u0006 אסור היין \u0005אף על פי שאין לו\u0006 דרך \u0005להשתמט]?\u0006 ומשיבים: \u0003לא,\u0004 מדובר \u0003בדאית ליה לאישתמוטי\u0004 \u0005[בשיש לו\u0006 דרך \u0005להשתמט],\u0006 ואם אין לו — היין מותר.","\u0003ההוא ישראל וגוי דהוו יתיבי וקא שתו חמרא\u0004 \u0005[שהיו יושבים\u0006 יחד \u0005והיו שותים יין],\u0006 \u0003שמע ישראל קל צלויי בי כנישתא\u0004 \u0005[קול תפילה בבית הכנסת],\u0006 \u0003קם ואזל\u0004 \u0005[עמד והלך]\u0006 להתפלל, ונשאלה שאלה בדינו של היין שנשאר שם. \u0003אמר רבא: חמרא שרי\u0004 \u0005[היין מותר],\u0006 מדוע? \u0003מימר\u0004 \u0005[אמור]\u0006 \u0003אמר\u0004 הגוי בליבו: \u0003השתא מדכר ליה לחמריה והדר אתי\u0004 \u0005[עכשיו נזכר\u0006 היהודי \u0005ביינו וחוזר ובא],\u0006 ולכן הוא חושש לנגוע בו.","\u0003ההוא ישראל וגוי דהוו יתיבי בארבא\u0004 \u0005[שהיו יושבים בספינה],\u0006 \u0003שמע ישראל קל שיפורי דבי שימשי\u0004 \u0005[\u0006את \u0005קול השופר של ערב שבת]\u0006 שמודיע על כניסת השבת, \u0003נפק ואזל\u0004 \u0005[יצא והלך]\u0006 לעיר לשבות שם. \u0003אמר רבא: חמרא שרי\u0004 \u0005[היין מותר],\u0006 \u0003מימר\u0004 \u0005[אמור]\u0006 \u0003אמר\u0004 הגוי בליבו: \u0003השתא מדכר ליה לחמריה והדר אתי\u0004 \u0005[עכשיו נזכר\u0006 היהודי \u0005ביינו וחוזר ובא].\u0006","ומעירים: \u0003ואי\u0004 \u0005[ואם]\u0006 תאמר שאין הגוי חושש \u0003משום שבתא\u0004 \u0005[השבת],\u0006 שהרי הוא יודע שהיהודי שומר שבת! \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רבא, אמר לי איסור גיורא\u0004 \u0005[הגר]:\u0006 \u0003כי הוינן בארמיותן\u0004 \u0005[כאשר היינו,\u0006 הייתי, \u0005בגויותינו]\u0006 \u0003אמרינן\u0004 \u0005[היינו אומרים]:\u0006 \u0003יהודאי לא מנטרי שבתא\u0004 \u0005[היהודים אינם שומרים שבת],\u0006 \u0003דאי מנטרי שבתא כמה כיסי קא משתכחי בשוקא\u0004 \u0005[שאם הם שומרים שבת\u0006 ואינם מטלטלים \u0005כמה כיסים\u0006 של כסף \u0005היו נמצאים בשוק],\u0006 משום שהיהודים אינם לוקחים אותם. \u0003ולא ידענא דסבירא לן\u0004 \u0005[ולא ידענו שסבורים אנו\u0006 להלכה\u0005]\u0006 \u0003כ\u0004דעת \u0003ר' יצחק,\u0004 ש\u0003אמר ר' יצחק: המוצא כיס בשבת\u0004 — \u0003מוליכו פחות פחות מארבע אמות,\u0004 שאף על פי שלכתחילה אין עושים כן התירו כאן.","\u0003ההוא אריא דהוה נהים במעצרתא\u0004 \u0005[אריה אחד שהיה נוהם ביקב],\u0006 \u0003שמע גוי\u0004 את קולו, ונבהל, \u0003טשא ביני דני\u0004 \u0005[\u0006ו\u0005התחבא בין החביות]\u0006 של יין, \u0003אמר רבא: חמרא שרי\u0004 \u0005[היין מותר],\u0006 ומדוע? \u0003מימר\u0004 \u0005[אמור]\u0006 \u0003אמר\u0004 הגוי בליבו: \u0003כי היכי דטשינא אנא\u0004 \u0005[כמו שאני מתחבא],\u0006 \u0003איטשא נמי\u0004 \u0005[מתחבא גם כן]\u0006 \u0003ישראל\u0004 מ\u0003אחוריי וקא חזי לי\u0004 \u0005[והוא רואה אותי].\u0006","ועוד מסופר, \u0003הנהו גנבי דסלקי\u0004 \u0005[אותם גנבים שבאו]\u0006 \u0003ל\u0004עיר \u0003פומבדיתא ופתחו חביתא טובא\u0004 \u0005[חביות\u0006 יין \u0005הרבה],\u0006 \u0003אמר רבא: חמרא שרי\u0004 \u0005[היין מותר],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003רובא גנבי\u0004 \u0005[רוב הגנבים]\u0006 \u0003ישראל נינהו\u0004 \u0005[הם],\u0006 ואנו הולכים אחר הרוב, ואין היין נאסר. \u0003הוה עובדא\u0004 \u0005[היה מעשה]\u0006 כגון זה \u0003בנהרדעי, ואמר שמואל: חמרא שרי\u0004 \u0005[היין מותר].\u0006","ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי],\u0006 האם לא \u0003כ\u0004דעת \u0003ר' אליעזר,\u0004 ש\u0003אמר: ספק ביאה\u0004 — \u0003טהור,\u0004 בכל מקום שלא ברור אם מישהו הגיע למקום מסויים או לא הגיע אנו מטהרים אותו? ומה עניינו?","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הנכנס לבקעה בימות הגשמים, וטומאה\u0004 היתה מצויה \u0003בשדה פלונית\u0004 בבקעה זו, \u0003ואמר:\u0004 יודע אני כי \u0003הלכתי במקום הלז\u0004 באותה בקעה, \u0003ואיני יודע אם נכנסתי לאותה שדה\u0004 שיש בה טומאה \u0003אם לא נכנסתי, ר' אליעזר אומר: ספק ביאה\u0004 אם ספק לו אם נכנס למקום — \u0003טהור, ספק מגע\u0004 אם יודע שנכנס למקום הטומאה, ורק ספק לו אם נגע בטומאה או לא — \u0003טמא.\u0004 ואילו חכמים מטמאים בכל מקרה.","ודוחים: \u0003לא,\u0004 אין לתלות את דברי שמואל בדברי ר' אליעזר, כי \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 לענין חביות היין, \u0003כיון דאיכא דפתחי לשום ממונא\u0004 \u0005[שיש שפותחים את\u0006 החביות רק \u0005לשם ממון]\u0006 שמחפשים כסף בחביות, ואם היה שם יין אינם מעוניינים בו, אם כן \u0003הוה ליה\u0004 \u0005[הרי זה]\u0006 \u0003ספק ספיקא\u0004 ספק אם גוים אם יהודים היו, וגם אם גוים היו — ספק אם נגעו או לא, ובכגון זה לדעת הכל אינו אוסר."],["עוד מסופר, \u0003ההיא רביתא דאישתכח דהות בי דני\u0004 \u0005[ילדה\u0006 גויה \u0005אחת שנמצאה שהיתה\u0006 עומדת \u0005בין החביות]\u0006 של יין, \u0003והות נקיטא אופיא\u0004 \u0005[והיתה מחזיקה קצף]\u0006 של יין \u0003בידה, אמר רבא: חמרא שרי\u0004 \u0005[היין מותר],\u0006 \u0003אימר מגבה דחביתא שקלתיה\u0004 \u0005[אמור מגב החבית לקחה אותו,\u0006 את הקצף\u0005]\u0006 ולא מתוך החבית עצמה. \u0003ואף על גב דליכא תו\u0004 \u0005[ואף על פי שאין עוד]\u0006 קצף כזה על גב החבית, \u0003אימר אתרמויי אתרמי לה\u0004 \u0005[אמור\u0006 ש\u0005נזדמן לה\u0006 קודם\u0005],\u0006 ולא נשאר שם יותר.","עוד מסופר, \u0003ההוא פולמוסא דסליק\u0004 \u0005[חיל צבא אחד שנכנס]\u0006 \u0003ל\u0004עיר \u0003נהרדעא, פתחו חביתא טובא\u0004 \u0005[חביות\u0006 יין \u0005הרבה],\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי אמר: עובדא הוה קמיה\u0004 \u0005[מעשה היה\u0006 שהביאו בעיה שכזו \u0005לפני]\u0006 \u0003ר' אלעזר, ושרא\u0004 \u0005[והתיר]\u0006 את היין. \u0003ולא ידענא\u0004 \u0005[ואין אני יודע],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום דסבר לה\u0004 \u0005[שסבור]\u0006 \u0003כ\u0004דעת \u0003ר' אליעזר\u0004 ש\u0003אמר\u0004 לענין ספק טומאה: \u0003ספק ביאה\u0004 אם נכנס למקום הטומאה — \u0003טהור,\u0004 או \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום דסבר\u0004 \u0005[שסבור\u0006 הוא\u0005]:\u0006 \u0003רובא דאזלי בהדי פולמוסא\u0004 \u0005[רוב\u0006 האנשים \u0005שהולכים עם הצבא]\u0006 — \u0003ישראל נינהו\u0004 \u0005[הם],\u0006 שאף על פי שהצבא עצמו היה של גוים, המלוים היו ישראלים.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 מפרשים יש לתמוה: וכי \u0003האי\u0004 \u0005[זה]\u0006 \u0003ספק ביאה?\u0004 הרי ברור שהאנשים הגיעו לשם ופתחו את החביות, ואם כן \u0003ספק מגע הוא,\u0004 האם נגעו ביין או לא נגעו, וגם ר' אליעזר מטמא בספק מגע! ומשיבים: \u0003כיון דמפתחי טובא\u0004 \u0005[\u0006שהיו \u0005פותחים\u0006 חביות \u0005רבות],\u0006 \u0003אימא אדעתא דממונא\u0004 \u0005[אמור\u0006 שמא ש\u0005על דעת ממון\u0006 בלבד\u0005]\u0006 \u0003פתחו,\u0004 למצוא שם כסף, ואין להם עניין ביין, \u0003וכספק ביאה דמי\u0004 \u0005[נחשב\u0006 הדבר\u0005]\u0006 להקל, ולא כספק מגע.","מסופר, \u0003ההיא מסוביתא\u0004 \u0005[מוזגת אחת]\u0006 ש\u0003מסרה לה איקלידא מפתחה\u0004 \u0005[\u0006את \u0005המנעול והמפתח שלה]\u0006 \u0003לגויה, אמר ר' יצחק אמר ר' אלעזר, עובדא הוה בי מדרשא\u0004 \u0005[מעשה כזה היה בבית המדרש]\u0006 שנשאלה שאלה כזו, \u0003ואמרו: לא מסרה לה אלא שמירת מפתח בלבד,\u0004 ולא התירה לה להיכנס, וממילא אין לחשוש שהגויה נכנסה וניסכה שם.","\u0003אמר אביי,\u0004 \u0003אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו\u0006 כגון זה\u0005]:\u0006 \u0003המוסר מפתחות לעם הארץ\u0004 אף על פי שמגעו מטמא — \u0003טהרותיו\u0004 של המוסר \u0003טהורות, לפי שלא מסר לו אלא שמירת מפתח בלבד,\u0004 ולא הרשה לו להיכנס. ויש ללמוד בקל וחומר: \u0003השתא\u0004 \u0005[עכשיו]\u0006 אם אנו אומרים \u0003טהרותיו טהורות, יין נסך מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שאין חוששים לו?","ותוהים על עצם ההנחה שבדבריו של אביי: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 מכאן ש\u0003טהרות אלימי\u0004 \u0005[חמורות]\u0006 \u0003מיין נסך?\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בנושא זה: \u0003חצר שחלקה\u0004 (שחילק אותה) \u0003במסיפס\u0004 בסורג דק, קטן, שנמוך מעשרה טפחים, \u0003אמר רב:\u0004 אם היה בצד השני עם הארץ — \u0003טהרותיו\u0004 של זה בחלק האחר של החצר \u0003טמאות,\u0004 אבל אם היה כגון זה \u0003בגוי\u0004 שהיה בצד השני — \u0003אינו עושה יין נסך. ור' יוחנן אמר: אף טהרותיו טהורות.\u0004 על כל פנים רואים מכאן שלשיטת רב מחמירים יותר בטהרות מאשר חוששים ליין נסך.","ועל שיטתו של רב בענין טהרות \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: היו שתי חצרות זו לפנים מזו, והיתה החצר \u0003הפנימית של חבר\u0004 שנזהר בדיני טהרה, \u0003והחיצונה של עם הארץ\u0004 שאינו נזהר בהם, \u0003אותו חבר שוטח שם\u0004 בחצר הפנימית \u0003פירות ומניח שם כלים, ואף על פי שידו של עם הארץ מגעת לשם.\u0004 אם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר \u0003ל\u0004דעת \u0003רב,\u0004 שהרי אף במקום שיש חלוקה ומחיצה חושש הוא למגע עם הארץ!","ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003רב: שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003שנתפס עליו כגנב,\u0004 שהרי בחצר הפנימית אין לו מה לעשות כלל, ואם הוא נכנס לשם הרי הוא נחשב כגנב, ואין אנו חוששים שיעשה כן.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לשיטתו של רב ממה ששנינו: \u0003רבן שמעון בן גמליאל אומר: גגו של חבר למעלה מגגו של עם הארץ, אותו חבר שוטח שם פירות ומניח שם כלים, ובלבד שלא תהא ידו של עם הארץ מגעת לשם,\u0004 שאם ידו של עם הארץ מגעת — טהרותיו של החבר טמאות. אם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר \u0003לר' יוחנן,\u0004 שהתיר טהרות בחצר שחילקה במסיפס!","ומשיבים, \u0003אמר לך\u0004 \u0005[יכול לומר לך]\u0006 \u0003ר' יוחנן: שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003דאית ליה לאישתמוטי\u0004 \u0005[שיש לו\u0006 לעם הארץ דרך \u0005להשתמט]\u0006 אם ימצאו אותו שולח ידו לגג העליון, \u0003מימר אמר\u0004 \u0005[אומר הוא]:\u0006 \u0003אימצורי קא ממצרא\u0004 \u0005[\u0006אני רוצה רק \u0005להתמתח]\u0006 ולכן הגבהתי את ידי, אבל לא התכוונתי לעשות דבר.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003גגו של חבר בצד גגו של עם הארץ, אותו חבר שוטח שם פירות ומניח שם כלים, ואף על פי שידו של עם הארץ מגעת לשם. קשיא\u0004 \u0005[קשה]\u0006 הדבר \u0003לרב!\u0004 ומשיבים: \u0003אמר לך\u0004 \u0005[יכול היה לומר לך]\u0006 \u0003רב: לאו איכא\u0004 \u0005[האם לא קיימת]\u0006 דעת \u0003רבן שמעון בן גמליאל דקאי כוותי\u0004 \u0005[שעומד כשיטתי]\u0006 בגגות סמוכים זה לזה? \u0003אנא דאמרי\u0004 \u0005[אני שאומר\u0006 את דברי\u0005]\u0006 הרי זה \u0003כ\u0004שיטת \u0003רבן שמעון בן גמליאל.\u0004","\u0003בולשת\u0004 (יחידה צבאית) \u0003שנכנסה לעיר\u0004 לשהות שם או לגבות מסים, אם היה הדבר \u0003בשעת שלום, חביות\u0004 יין \u0003פתוחות\u0004 — \u0003אסורות,\u0004 אם היו \u0003סתומות\u0004 — \u0003מותרות;\u0004 אם היה זה \u0003בשעת מלחמה\u0004 — \u0003אלו ואלו מותרות\u0004 ואפילו הפתוחות, \u0003לפי שאין פנאי\u0004 לחיילים \u0003לנסך.\u0004"],["שנינו במשנתנו כי בשעת מלחמה אין לאנשי הצבא פנאי, ואין לחשוש שעברו עבירה. \u0003ורמינהי\u0004 \u0005[ומקשים]\u0006 על כך ממה ששנינו במשנה אחרת: \u0003עיר שכבשוה כרקום\u0004 (צבא העורך מצור על עיר) — \u0003כל כהנות שבתוכה פסולות,\u0004 שאנו חוששים שמא נאנסו על ידי חיילי הצבא, ואף על פי ששעת מלחמה היא! \u0003אמר רב מרי: לנסך אין פנאי\u0004 שהם חוששים מן המלחמה, ואין יצר הניסוך גדול באותה שעה. אבל \u0003לבעול יש פנאי,\u0004 שיצר זה גדול, ואפילו בזמן מלחמה.","\u0003האומנין של ישראל\u0004 (כלומר, ישראלים) \u0003ששלח להם נכרי חבית של יין נסך בשכרן\u0004 (תמורת עבודתם), והרי הוא אסור בהנאה — \u0003מותר\u0004 להם \u0003לומר\u0004 לו: \u0003\"תן לנו את דמיה\"\u0004 כמה שהיא שווה, אבל אם \u0003משנכנסה\u0004 החבית \u0003לרשותן\u0004 — \u0003אסור\u0004 לקבל מן הגוי גם את דמיה, שהרי זה כאילו מכרו יין נסך, ונהנו מדמיו.","\u0003אמר רב יהודה אמר רב: מותר לאדם לומר לגוי: \"צא והפס עלי מנת המלך\"\u0004 כלומר, השתדל עבורי לפייס את השלטונות הגובים את המס מן היין, ואני אחזיר לך לאחר מכן. גם אם אותו גוי ישלם את המס ביין נסך.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003אל יאמר אדם לגוי: \"עול תחתי לעוצר\"\u0004 כלומר, שלם במקומי לגובה היין, כשהגוי משלם ביין נסך! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב: \"עול תחתי לעוצר\" קאמרת\u0004 \u0005[אומר אתה]?\u0006 כיון שאומר בלשון \"תחתי\" הרי זה כאילו הגוי עושה זאת במקומו. \u0003הא לא דמיא\u0004 \u0005[זה אינו דומה]\u0006 \u0003אלא להא\u0004 \u0005[לזו]\u0006 ששנינו, \u0003אבל אומר לו\u0004 יכול אדם לומר לגוי: \u0003\"מלטני מן העוצר\"\u0004 כלומר, מצא דרך למלט אותי ממס זה על ידי שתשלם אתה לגובה המס. שאף רב אינו מדבר במקרה שמבקש מן הגוי להיכנס במקומו, אלא רק שיצילנו.","\u0003המוכר יינו לנכרי,\u0004 אם \u0003פסק\u0004 נקבע והוסכם המחיר \u0003עד שלא\u0004 (בטרם) \u0003מדד\u0004 לכליו של הגוי את כמות היין הנמכר — \u0003דמיו\u0004 של היין \u0003מותרין,\u0004 ואין הוא נחשב כמוכר יין נסך, שהרי קנה הגוי את היין קודם שייאסר, וכבר אז היו הדמים שייכים לישראל. אבל אם \u0003מדד\u0004 את היין לכליו של הגוי, וכבר נאסר \u0003עד שלא פסק\u0004 דמים, קודם שנקנה היין לגוי — \u0003דמיו אסורין,\u0004 משום שנעשה כמוכר יין נסך שאסור בהנאה.","\u0003אמר אמימר: משיכה בגוי קונה\u0004 שכאשר גוי מושך חפץ לשם קנין, נגמר הקנין על ידי המשיכה עצמה. \u0003תדע\u0004 שכן הוא, \u0003דהני פרסאי משדרי פרדשני להדדי ולא הדרי בהו\u0004 \u0005[שהרי אותם פרסים שולחים מתנות זה לזה ולא חוזרים בהם],\u0006 משמע שהם קונים זה מזה על ידי משיכה בלבד! \u0003רב אשי אמר, לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 ש\u0003משיכה בגוי אינה קונה, והאי דלא הדרי בהו\u0004 \u0005[וזה שאינם חוזרים בהם],\u0006 לא משום שהוא מדיני קנין, אלא משום \u0003דרמות רוחא הוא דנקיטא להו\u0004 \u0005[שגסות הרוח היא שאחוזה בהם],\u0006 שלא נאה להם לחזור בהם.","\u0003אמר רב אשי: מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה]\u0006 שאין משיכה קונה בגוי? \u0003מדאמר להו\u0004 \u0005[מ\u0006מה \u0005שאמר להם]\u0006 \u0003רב להנהו סבויתא\u0004 \u0005[לאותם מוכרי יין]:\u0006 \u0003כי כייליתו חמרא\u0004 \u0005[כאשר אתם מודדים יין]\u0006 \u0003לגוים, שקלו זוזי מינייהו והדר כיילן להו\u0004 \u0005[טלו\u0006 את \u0005הכסף מהם ואחר כך מדדו להם].\u0006 \u0003ואי לא נקיטו בהדייהו זוזי\u0004 \u0005[ואם אינם מחזיקים אותם\u0006 בידם \u0005כסף],\u0006 \u0003אוזיפונהו והדר שקילו מינייהו\u0004 \u0005[הלוו להם ואחר כך טלו מהם]\u0006 כסף זה כדמי היין, \u0003כי היכי דתיהוי\u0004 \u0005[כדי שתהיה]\u0006 זו \u0003הלואה גבייהו\u0004 \u0005[אצלם],\u0006 שמה שישלמו לכם לאחר שיקנו את היין לא יהיה אלא החזרת החוב. \u0003דאי לא עבדיתו הכי\u0004 \u0005[שאם אין אתם עושים כך],\u0006 אלא מודדים תחילה, \u0003כי קא הוי\u0004 \u0005[כאשר הוא נעשה]\u0006 \u0003יין נסך\u0004 — \u0003ברשותייכו קא הוי\u0004 \u0005[ברשותכם הוא נעשה],\u0006 \u0003וכי שקילתו\u0004 \u0005[וכאשר אתם נוטלים\u0006 כסף עבורו\u0005]\u0006 \u0003דמי יין נסך קא שקילתו\u0004 \u0005[אתם לוקחים].\u0006 ומכאן יש להוכיח: \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה בדעתך]\u0006 ש\u0003משיכה בגוי קונה,\u0004"],["\u0003מדמשכה\u0004 \u0005[מ\u0006שעה \u0005שמשך אותו]\u0006 ה\u0003גוי קנייה\u0004 \u0005[קנה אותו],\u0006 ואילו \u0003יין נסך\u0004 \u0003לא הוי\u0004 \u0005[נהיה]\u0006 \u0003עד דנגע ביה\u0004 \u0005[שיגע בו],\u0006 ואם כן, יכול המוכר לקבל את מחיר היין שמכר, שהרי בשעת הקנין היה יין כשר!","ודוחים: \u0003אי דקא כייל ורמי למנא\u0004 \u0005[אם\u0006 במקרה \u0005ש\u0006המוכר \u0005מודד ושופך לכלי]\u0006 של \u0003ישראל, הכי נמי\u0004 \u0005[כך\u0006 הוא \u0005גם כן]\u0006 הדין, ואולם הוראתו זו של רב \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דקא כייל ורמי למנא\u0004 \u0005[שהוא מודד ושופך לכלי]\u0006 של ה\u0003גוי\u0004 שיש בו יין נסך, וכך הוא נאסר עוד קודם שקנה אותו.","ומקשים: \u0003סוף סוף,\u0004 גם במקרה כזה, \u0003כי מטא לאוירא דמנא קנייה\u0004 \u0005[\u0006מיד \u0005כאשר\u0006 היין \u0005מגיע לאויר,\u0006 לחלל \u0005של הכלי קונה אותו\u0006 הגוי\u0005],\u0006 ואילו \u0003יין נסך\u0004 הוא \u0003לא הוי\u0004 \u0005[נהיה]\u0006 \u0003עד דמטי לארעיתיה דמנא\u0004 \u0005[ש\u0006הוא \u0005מגיע לקרקעיתו של הכלי],\u0006 ויש כאן קנין קודם לאיסור. האם \u0003שמע מינה\u0004 \u0005[נלמד מכאן]\u0006 שלדעת רב \u0003נצוק\u0004 (סילון, זרם) הוא \u0003חבור,\u0004 ונחשב כאילו היין האסור שבקרקעית הכלי והיין ששופכים לתוכו מחוברים זה לזה?","ודוחים: \u0003לא,\u0004 ניצוק אינו חיבור, ולכן, \u0003אי דנקיט ליה גוי לכלי בידיה\u0004 \u0005[אם מחזיק הגוי את הכלי בידו]\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 הדין, שהקנין קודם והדמים מותרים. ואולם \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הוראה זו של רב אלא במקרה \u0003דמנח אארעא\u0004 \u0005[ש\u0006הכלי של הגוי \u0005מונח על הקרקע]\u0006 של מוכר היין, ולכן לא נקנה לגוי קודם שייאסר.","ושואלים: \u0003ותיקני ליה\u0004 \u0005[שיקנו לו]\u0006 \u0003כליו\u0004 של הגוי את היין משיגיע לחלל הכלי! ואם אין אומרים כן, \u0003שמעת מינה\u0004 \u0005[\u0006האם \u0005לומד אתה מכאן]\u0006 הלכה כללית לדעת רב, שאם היו \u0003כליו של לוקח ברשות מוכר\u0004 — \u0003לא קנה לוקח\u0004 דבר שנכנס לכליו? ודבר זה הרי מסופק לחכמים, ונשאר במקורו כבעיה בלתי פתורה!","ודוחים: \u0003לא, לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 בכלל: \u0003קנה לוקח, והכא במאי עסקינן\u0004 \u0005[וכאן,\u0006 שהיין נאסר קודם שנקנה לגוי, \u0005במה אנו עוסקים]?\u0006 \u0003כגון דאיכא\u0004 \u0005[שיש]\u0006 \u0003עכבת\u0004 \u0003יין אפומיה דכוזנתא\u0004 \u0005[על פי הכד]\u0006 של הגוי, שיש מעט יין נסך, ומשום כך נאסר היין הנשפך אל הכד, \u0003דקמא קמא אינסיך\u0004 \u0003ליה\u0004 \u0005[שהראשון ראשון\u0006 שנשפך \u0005מתנסך לו]\u0006 מפני שמתערב ביין הנסך הנמצא שם. ולכן אמר רב למוכרי היין שיטלו את דמי היין קודם שימדוד לכלי הגוי.","ומעירים: \u0003ו\u0004להסבר זה, \u0003כמאן\u0004 \u0005[כדעת מי]\u0006 אמר רב דבר זה? ש\u0003לא כ\u0004שיטת \u0003רבן שמעון בן גמליאל, דאי\u0004 \u0005[שאם]\u0006 כדעת \u0003רבן שמעון בן גמליאל, האמר\u0004 \u0005[הרי אמר]:\u0006 שיין נסך שנתערב ביין אחר \u0003ימכר\u0004 היין \u0003כולו לנכרים חוץ מדמי יין נסך שבו,\u0004 ומותר איפוא ליטול דמים עבור היין שנשפך לכלי הגוי, ואנו פוסקים הלכה כמותו!","ומשיבים: \u0003מידי הוא טעמא\u0004 \u0005[כלום\u0006 לא הוסבר \u0005הטעם]\u0006 של ההלכה הזו \u0003אלא ל\u0004דעת \u0003רב, האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רב: הלכה כרבן שמעון בן גמליאל\u0004 דווקא כשנתערבה \u0003חבית בחבית, אבל לא יין ביין,\u0004 שאז היין כולו אסור, וגם דמיו. ונמצא על כל פנים, כי אין ראיה מדברי רב שמשיכה אינה קונה בגוי.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד על דברי אמימר ממה ששנינו: \u0003הלוקח גרוטאות מן הגוים ומצא בהן עבודה זרה, אם עד שלא נתן\u0004 עבורם \u0003מעות\u0004 לגוי \u0003משך\u0004 את הגרוטאות — \u0003יחזיר\u0004 את הגרוטאה הזו של עבודה זרה, לפי שלא זכה בה עדיין. \u0003אם משנתן מעות משך\u0004 — \u0003יוליך\u0004 את העבודה הזרה הזו \u0003לים המלח,\u0004 ששלו היא, וחייב לבערה. ומעתה, \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 ש\u0003משיכה בגוי קונה\u0004 כדברי אמימר, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003יחזיר\u0004 כשמשך? הרי כבר שלו היא! \u0003אמר אביי: משום דמיחזי כי\u0004 \u0005[שנראה\u0006 הדבר \u0005כמו]\u0006 \u0003מקח טעות,\u0004 שוודאי לא התכוון לקנות עבודה זרה.","\u0003אמר רבא:\u0004 ומדוע במקרה השני, שנתן מעות, אינו יכול להחזיר? וכי \u0003רישא\u0004 \u0005[בתחילה]\u0006 הוא \u0003מקח טעות, סיפא לאו\u0004 \u0005[בסוף אינו]\u0006 \u0003מקח טעות? אלא אמר רבא: רישא וסיפא\u0004 \u0005[בראש ובסוף]\u0006 הרי זה \u0003מקח טעות, ו\u0004לכן \u0003רישא\u0004 \u0005[בתחילה]\u0006 ש\u0003לא יהיב זוזי\u0004 \u0005[נתן\u0006 עדיין \u0005כסף],\u0006 \u0003לא מיתחזי\u0004 \u0005[נראה]\u0006 הדבר \u0003כעבודה זרה ביד ישראל,\u0004 ולכן יכול הוא להחזיר אותה, ואילו \u0003סיפא דיהיב זוזי\u0004 \u0005[הסוף שנתן כסף]\u0006 \u0003מיתחזי\u0004 \u0005[נראה\u0006 הדבר\u0005]\u0006 \u0003כעבודה זרה ביד ישראל,\u0004 ומשום מראית העין חייב לבערה.","ומעתה מביאים ראיות נגד שיטת רב אשי, הסבור שגוי אינו קונה במשיכה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר קשישא\u0004 \u0005[הזקן]\u0006 \u0003בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חסדא לרב אשי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממשנתנו, ששנינו: \u0003המוכר יינו לנכרי,\u0004 אם \u0003פסק\u0004 את מחירו \u0003עד שלא מדד\u0004 — \u0003דמיו מותרים,\u0004 מאחר וכבר נקנה היין לגוי קודם שנגע בו. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003משיכה בגוי אינה קונה, אמאי\u0004 \u0005[מדוע]\u0006 \u0003דמיו מותרין?\u0004 השיב לו רב אשי: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003דאקדים ליה\u0004 \u0005[שהקדים\u0006 ושילם \u0005לו]\u0006 \u0003דינר\u0004 על החשבון, קודם המדידה, ובכך קנה את היין בכסף.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שמדובר שהקדים לו, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005]:\u0006 \u0003מדד עד שלא פסק\u0004 — \u0003דמיו אסורין; ואי דקדים ליה\u0004 \u0005[ואם הקדים לו]\u0006 \u0003דינר, אמאי\u0004 \u0005[מדוע]\u0006 \u0003דמיו אסורין?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003ולדידך דאמרת\u0004 \u0005[ולשיטתך שאומר אתה]\u0006 \u0003משיכה בגוי קונה, אמאי רישא\u0004 \u0005[מדוע בהתחלה]\u0006 \u0003דמיו מותרין, וסיפא\u0004 \u0005[ובסוף]\u0006 \u0003דמיו אסורין?\u0004","\u0003אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]\u0006 שאתה מחלק בין הדברים? שאתה אומר כך: כאשר \u0003פסק\u0004 \u0005[פוסק]\u0006 מחיר — \u0003סמכא דעתיה\u0004 \u0005[סומכת\u0006 \u0005דעתו]\u0006 שלא תתבטל המכירה, ולכן המכירה נגמרת במשיכה, אבל כאשר \u0003לא פסק\u0004 \u0005[פוסק]\u0006 — \u0003לא סמכא דעתיה\u0004 \u0005[אין דעתו סומכת\u0006 על כך\u0005].\u0006","\u0003לדידי נמי\u0004 \u0005[לשיטתי גם כן],\u0006 \u0003אף על גב דקדים ליה\u0004 \u0005[אף על פי שהקדים לו]\u0006 \u0003דינר,\u0004 אם \u0003פסק\u0004 \u0005[פוסק]\u0006 לו מחיר — \u0003סמכא דעתיה\u0004 \u0005[סומכת דעתו],\u0006 \u0003לא פסק\u0004 \u0005[פוסק]\u0006 מחיר — \u0003לא סמכא דעתיה\u0004 \u0005[לא סומכת דעתו].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת נגד שיטתך, ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: בן נח נהרג על\u0004 גזילה של \u0003פחות משוה פרוטה, ו\u0004אולם בגזל כזה שהוא פחות משוה פרוטה, אם גזל את ישראל — \u0003לא ניתן להישבון\u0004 אינו חייב להשיבו לישראל, מאחר שישראל אינו מקפיד על כך. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003משיכה בגוי אינה קונה, אמאי\u0004 \u0005[מדוע]\u0006 \u0003נהרג\u0004 הגוי? הרי לא עשה דבר על ידי זה שגזל חפץ, שהרי החפץ נשאר קנין בעליו הראשונים!","ומשיבים: \u0003משום דצעריה\u0004 \u0005[שציער]\u0006 את \u0003ישראל\u0004 על ידי לקיחה זו, שלקח ממון שאינו שלו, אף על פי שמבחינת דיני הקניינים לא קנה."],["\u0003ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"לא ניתן להישבון\"?\u0004 ש\u0003אינו בתורת הישבון\u0004 אינו בכלל דין השבת גזילה, שהרי באמת לא גזל את החפץ.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של הלכה זו: גוי שגזל מישראל, ו\u0003בא חבירו\u0004 שהוא גם כן גוי \u0003ונטלה ממנו\u0004 — \u0003נהרג עליה. בשלמא רישא\u0004 \u0005[נניח בראש]\u0006 בהלכה הראשונה אתה מפרש \u0003משום דצעריה\u0004 \u0005[שציער]\u0006 את \u0003ישראל, אלא סיפא\u0004 \u0005[בסוף]\u0006 \u0003מאי עביד\u0004 \u0005[מה עשה]\u0006 השני?","\u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003משיכה בגוי קונה,\u0004 ולכן קנה הראשון את הגזילה, ומשום כך גם חייב השני שגזלה ממנו. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ובענין פסיקת דמים שנזכרה במשנתנו, מסופר, \u0003ההוא גברא\u0004 \u0003דאמר ליה לחבריה\u0004 \u0005[אדם אחד שאמר לו לחבירו]:\u0006 \u0003\"אי מזביננא לה להא ארעא\u0004 — \u0003לך מזביננא לה\"\u0004 \u0005[אם מוכר אני את הקרקע הזו, לך אמכור אותה],\u0006 \u0003אזל זבנה לאיניש אחרינא\u0004 \u0005[הלך\u0006 ו\u0005מכר אותה לאיש אחר],\u0006 \u0003אמר רב יוסף: קנה קמא\u0004 \u0005[הראשון]\u0006 שעימו התנה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא\u0004 \u0005[והרי]\u0006 \u0003לא פסק\u0004 עימו את המחיר! \u0003ומנא תימרא דכל היכא\u0004 \u0005[ומנין אתה אומר שכל מקום]\u0006 ש\u0003לא פסק לא קנה\u0004 \u0005[קונה]?\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנתנו\u0005]:\u0006 \u0003המוכר יינו לנכרי, פסק עד שלא מדד\u0004 — \u0003דמיו מותרין, מדד עד שלא פסק\u0004 — \u0003דמיו אסורין.\u0004","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]?\u0006 מה נאמר על ראיה זו? ותוהים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]?\u0006 \u0003כדקאמרינן\u0004 \u0005[כמו שאמרנו]\u0006 הרי יש לנו הוכחה מפורשת מן המשנה שהפסיקה היא הקובעת! ומשיבים: משם אי אפשר להוכיח הוכחה גמורה, \u0003דלמא חומרא\u0004 \u0005[שמא חומרת]\u0006 \u0003יין נסך שאני\u0004 \u0005[שונה],\u0006 שמשום כך מקפידים יותר בדבר, אבל בענין אחר לא מקפידים כל כך על הפסיקה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ש\u0003אמר רב אידי בר אבין: עובדא הוה בי\u0004 \u0005[מעשה היה בבית]\u0006 \u0003רב חסדא, ורב חסדא\u0004 היה לו מעשה כגון זה \u0003בי\u0004 \u0005[בבית]\u0006 \u0003רב הונא, ופשטיה מהא דתנן\u0004 \u0005[ופתרו\u0006 את הבעיה \u0005מזו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003משך חמריו ופועליו\u0004 של המוכר, שהיו טעונים פירות, \u0003והכניסן לתוך ביתו, בין פסק עד שלא מדד ובין מדד עד שלא פסק\u0004 — \u0003לא קנה, ושניהן,\u0004 בין המוכר ובין הקונה, \u0003יכולין לחזור בהן\u0004 משום שעדיין לא עשה מעשה של קנין בפירות.","אבל \u0003פרקן\u0004 פירק את המשא שהביאו עימהם \u0003והכניסן לתוך ביתו,\u0004 וכך נעשה מעשה של קנין, שנכנסו לרשותו, אם \u0003פסק עד שלא מדד\u0004 — \u0003אין שניהן יכולין לחזור בהן, מדד עד שלא פסק\u0004 — \u0003שניהן יכולין לחזור בהן,\u0004 משמע מכאן שלמרות שנעשה קנין, יכולים הצדדים לחזור בהם עד שיפסקו את המחיר, וכדברי אביי.","ובענין דומה של פסיקת מחיר, מסופר, \u0003ההוא גברא\u0004 \u0003דאמר ליה לחבריה\u0004 \u0005[אדם אחד שאמר לו לחבירו]:\u0006 \u0003\"אי מזביננא לה להא ארעא\u0004 — \u0003מזביננא לך במאה זוזי\u0004 \u0005[אם אני מוכר את הקרקע הזו\u0006 \u0005אמכור אותה לך במאה זוזים],\u0006 \u0003אזל זבנה לאיניש אחרינא\u0004 \u0005[הלך\u0006 ו\u0005מכר אותה לאיש אחר]\u0006 \u0003במאה ועשרין\u0004 \u0005[ועשרים],\u0006 \u0003אמר רב כהנא: קנה קמא\u0004 \u0005[הראשון].\u0006 \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יעקב מנהר פקוד: האי זוזי אנסוהו\u0004 \u0005[\u0006אדם \u0005זה הכסף אנס אותו]\u0006 שאמנם התחייב למוכרה לו כשירצה למכור, אבל במקרה זה אין רצונו למכור, אלא כאילו נאנס מחמת הכסף שהוצע לו, ולכן מכירתו האחרונה תקפה. ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כרב יעקב מנהר פקוד.\u0004","ועוד בענין התחייבות מוקדמת של אדם למחיר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 המוכר לקונה שהוא מוכר דבר במחיר \u0003\"כדשיימי בתלתא\"\u0004 \u0005[כמו שיעריכו\u0006 אותו \u0005בשלושה]\u0006 — \u0003אפילו תרי מגו תלתא\u0004 \u0005[שנים מתוך שלושה]\u0006 פסקו על סכום מסויים, הרי זה בכלל מה שקיבל על עצמו. אבל אם אמר: \u0003\"כדאמרי בתלתא\"\u0004 \u0005[כמו שאומרים שלושה]\u0006 הכוונה היא \u0003עד דאמרי בתלתא\u0004 \u0005[שיאמרו שלושתם]\u0006 דבר אחד. אם הוא אומר \u0003\"כדשיימי\u0004 \u0005[כמו ששמים]\u0006 \u0003בארבעה\"\u0004 — \u0003עד דאמרי\u0004 \u0005[שיאמרו]\u0006 \u0003בארבעה, וכל שכן היכא דאמר ליה \"כדאמרי בארבעה\"\u0004 \u0005[כשאמר לו: \"כמו שאומרים ארבעה\"].\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"כדשיימי בתלתא\"\u0004 \u0005[כמו שיעריכו בשלושה],\u0006 \u0003ואתו תלתא ושמוה\u0004 \u0005[ובאו שלושה והעריכו אותה],\u0006 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003אידך\u0004 \u0005[האחר]:\u0006 \u0003ליתו תלתא אחריני דקים להו טפי\u0004 \u0005[שיבואו שלושה אחרים שמוחזק להם,\u0006 מבינים \u0005יותר\u0006 בדבר\u0005]\u0006 — \u0003אמר רב פפא: דינא\u0004 \u0005[דין]\u0006 \u0003הוא\u0004 ש\u0003מעכב\u0004 עד שיבואו השלושה האחרים. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: ממאי דהני קים להו טפי\u0004 \u0005[מנין שאלה מוחזק להם,\u0006 מבינים \u0005יותר]?\u0006 \u0003דלמא הני קים להו טפי\u0004 \u0005[שמא אלה\u0006 הראשונים \u0005מוחזק להם יותר]!\u0006 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כרב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע,\u0004 שכיון ששמוהו שלושה הראשונים — הולכים לפיהם.","\u0003נטל את המשפך\u0004 של יין \u0003ומדד לתוך צלוחיתו של נכרי, וחזר ומדד\u0004 באותו משפך יין \u0003לתוך צלוחיתו של ישראל, אם יש בו\u0004 במשפך \u0003עכבת יין\u0004 שמתעכב בתוכו משהו מן היין — כל מה ששפך דרכו לכלי של ישראל \u0003אסור,\u0004 מאחר ונתערב בו אותו יין. \u0003המערה מכלי אל כלי, את\u0004 (אותו כלי) \u0003שעירה ממנו\u0004 — \u0003מותר, ואת שעירה לתוכו\u0004 — \u0003אסור.\u0004","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת טהרות: \u0003הנצוק\u0004 קילוח של נוזלים, \u0003והקטפרס\u0004 מים הזורמים במדרון, \u0003ומשקה\u0004 נוזל בכמות כזו שהוא \u0003טופח\u0004 מרטיב מה שהוא נוגע בו, ולא יותר מכך — כל אחד מאלה \u0003אינו\u0004 מהווה \u0003חיבור\u0004 בין נוזלים \u0003לא ל\u0004ענין \u0003טומאה ולא ל\u0004ענין \u0003טהרה.\u0004 \u0003האשבורן\u0004 משקה מכונס במקום אחד (ויש בו טופח על מנת להטפיח) — הרי זה \u0003חיבור לטומאה ולטהרה.\u0004","\u0003אמר רב הונא: נצוק וקטפרס ומשקה טופח\u0004 — הרי הם \u0003חיבור לענין יין נסך.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לרב הונא: מנא לך הא\u0004 \u0005[מנין לך\u0006 דבר \u0005זה]?\u0006 \u0003אילימא מדתנן\u0004 \u0005[אם תאמר\u0006 מדיוק הלשון, \u0005ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הנצוק והקטפרס ומשקה טופח\u0004 — \u0003אינו חיבור לא לטומאה ולא לטהרה,\u0004 ואתה מדייק מכאן: \u0003לטומאה ולטהרה הוא דלא הוי\u0004 \u0005[שאינו]\u0006 \u0003חיבור, הא\u0004 \u0005[הרי]\u0006 \u0003לענין יין נסך הוי\u0004 \u0005[הרי זה]\u0006 \u0003חיבור.\u0004 אם כן, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה: \u0003האשבורן\u0004 — \u0003חיבור לטומאה ולטהרה,\u0004 ונדייק מכאן: \u0003לטומאה ולטהרה הוא דהוי\u0004 \u0005[שהוא]\u0006 \u0003חיבור, הא\u0004 \u0005[הרי]\u0006 \u0003לענין יין נסך לא הוי\u0004 \u0005[אין זה]\u0006 \u0003חיבור,\u0004 ודאי אי אפשר לומר כן! \u0003אלא מהא ליכא למשמע מינה\u0004 \u0005[מזו\u0006 מדיוק לשון הזה \u0005אין לשמוע ממנו].\u0006 ומנסים להביא ראיה לשיטת רב הונא ממשנתנו.","\u0003תנן\u0004 \u0005[שנינו]:\u0006 \u0003נטל את המשפך ומדד לתוך צלוחיתו של נכרי, וחזר ומדד לתוך צלוחיתו של ישראל,\u0004"],["\u0003אם יש בו עכבת יין\u0004 — \u0003אסור.\u0004 ויש לשאול: \u0003הא\u0004 \u0005[זו]\u0006 \u0003עכבת יין במאי קא מתסרא\u0004 \u0005[במה היא נאסרת]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003בנצוק,\u0004 מפני שהיין היורד מחבר את מה שבכלי (שהוא יין אסור, של גוי) לעכבה שבמשפך? \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003נצוק\u0004 הריהו \u0003חיבור!\u0004","ומשיבים: \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא\u0004 במשנתו, שמדובר כאן במקרה \u0003שפחסתו צלוחיתו,\u0004 שהצלוחית התחתונה נתרבה בה היין עד שעלה למשפך עצמו. ומסיקים: \u0003אבל\u0004 במקרה רגיל של משפך ש\u0003לא פחסתו צלוחיתו מאי\u0004 \u0005[מה]\u0006 יהא הדין? \u0003לא\u0004 יהיה אסור. אם כן \u0003תפשוט\u0004 \u0005[תפתור\u0006 מכאן\u0005]\u0006 ש\u0003נצוק אינו חיבור!\u0004 ודוחים: \u0003לא,\u0004 מכאן אין ראיה, אלא רק לענין \u0003פחסתו צלוחיתו תפשוט לך\u0004 \u0005[תפתור\u0006 מכאן\u0005]\u0006 ש\u0003אסור,\u0004 אבל בענין \u0003נצוק\u0004 עדיין \u0003תיבעי\u0004 \u0005[תישאל]\u0006 השאלה.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מן הדין השני ששנינו במשנתנו: \u0003המערה מכלי לכלי, את\u0004 (הכלי) \u0003שמערה ממנו\u0004 — \u0003מותר\u0004 היין שבו, ונלמד מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 סילון היין עצמו \u0003דביני ביני\u0004 \u0005[שבאמצע]\u0006 שיצא מן הכלי ונגע בכלי התחתון — \u0003אסור, שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003נצוק\u0004 הריהו \u0003חיבור.\u0004","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 אתה אומר ש\u0003נצוק חיבור, אפילו דגויה דמנא נמי ליתסר\u0004 \u0005[\u0006היין \u0005ש\u0006נמצא \u0005תוך הכלי\u0006 שעירה ממנו \u0005גם כן ייאסר]!\u0006 ודוחים: \u0003הא לא קשיא, דקא מקטיף קטופי\u0004 \u0005[זה אינו קשה,\u0006 יש לפרש \u0005שהוא שופך בקפיצות],\u0006 ואין קילוח רצוף המחבר את מה שבשני הכלים. ואומרים: \u0003מכל מקום\u0004 אנו למדים מכאן שסילון היין נאסר עוד לפני שנכנס לכלי, ונמצא כי \u0003נצוק\u0004 הריהו \u0003חיבור!\u0004","ודוחים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 ולשיטתך\u0005]\u0006 שאתה מדייק בדרך זו, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של אותה הלכה: \u0003את שעירה לתוכו הוא דאסיר\u0004 \u0005[שאסור],\u0006 ונדייק: \u0003הא דביני ביני שרי\u0004 \u0005[הרי מה שבאמצע מותר],\u0006 אף שהיה חיבור על ידי ניצוק, והוא ההיפך ממה שדייקת מתחילת ההלכה! \u0003אלא, מהא ליכא למשמע מינה\u0004 \u0005[מזו אין ללמוד ממנה]\u0006 מאופן דיוק זה.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מברייתא: \u0003המערה\u0004 יין \u0003מחבית לבור\u0004 שיש בו יין אסור, \u0003קילוח היורד משפת חבית למטה\u0004 — \u0003אסור,\u0004 משמע שניצוק הוא חיבור, שהרי קילוח זה נאסר רק משום שקצהו התחתון נוגע ביין האסור שבבור! \u0003תרגמה\u0004 \u0005[תרגם,\u0006 הסביר אותה\u0005]\u0006 \u0003רב ששת\u0004 משנה זו, לא ביין ששופך ישראל לבור שיש בו יין אסור, ומדין ניצוק, אלא \u0003בגוי המערה\u0004 מן החבית לבור, והיין שיצא מן החבית נאסר משום \u0003דאתי\u0004 \u0005[שבא]\u0006 \u0003מכחו\u0004 של גוי.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר ב\u0003גוי המערה, אפילו גוא דחביתא נמי מתסר\u0004 \u0005[\u0006היין שב\u0005תוך החבית גם כן נאסר]\u0006 משום שהגוי מנענע אותו בכוחו! ומשיבים: \u0003כח\u0004 של \u0003גוי מדרבנן\u0004 \u0005[מדברי סופרים\u0006 \u0003הוא דאסיר\u0004 \u0005[שאסור],\u0006 \u0003ההוא דנפק לבראי\u0004 \u0005[אותו\u0006 היין \u0005שיצא החוצה]\u0006 — \u0003גזרו ביה רבנן\u0004 \u0005[בו חכמים],\u0006 \u0003ההוא דלגואי\u0004 \u0005[אותו שבפנים]\u0006 — \u0003לא גזרו ביה רבנן\u0004 \u0005[בו חכמים].\u0006 ומביאים כיצד נהגו חכמים למעשה בענין זה.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב חסדא להנהו סביתא\u0004 \u0005[לאותם מוכרי יין]:\u0006 \u0003כי כייליתו חמרא\u0004 \u0005[כאשר אתם מודדים יין]\u0006 \u0003לגוים\u0004 לכלים שלהם — \u0003קטפי קטופי\u0004 \u0005[שפכו בקפיצה],\u0006 כלומר, אל תשפכו זרם שהוא מתמשך, אלא הפסיקו בכל פעם, \u0003אי נמי נפצי נפוצי\u0004 \u0005[או גם כן העבירו בזריקה]\u0006 בבת אחת אך לא על ידי שפיכה, על מנת שלא יהא קילוח רצוף של יין מן הכלי שלכם לכלי של הגוי. ועוד מסופר, \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא להנהו שפוכאי\u0004 \u0005[לאותם שופכי יין]\u0006 שהיו מעבירים יין מכלי לכלי: \u0003כי שפכיתו חמרא\u0004 \u0005[כאשר אתם שופכים יין],\u0006 ש\u0003לא ליקרב\u0004 \u0005[יתקרב]\u0006 \u0003גוי לסייע בהדייכו\u0004 \u0005[לכם],\u0006 \u0003דלמא משתליתו ושדיתו ליה עליה\u0004 \u0005[שמא תשכחו ותטילו\u0006 את הכלי \u0005עליו]\u0006 כדי שיעזור לכם, \u0003וקאתי\u0004 \u0005[ויבוא]\u0006 היין \u0003מכחו, ואסיר\u0004 \u0005[ואסור].\u0006","מסופר, \u0003ההוא גברא דאסיק חמרא בגישתא ובת גישתא\u0004 \u0005[אדם אחד שהעלה יין\u0006 מן החבית \u0005על ידי קנה ובן קנה],\u0006 \u0003אתא גוי אנח ידיה אגישתא\u0004 \u0005[בא גוי\u0006 ו\u0005הניח\u0006 את \u0005ידו על פי הקנה]\u0006 ונגע ביין, \u0003אסריה\u0004 \u0005[אסר]\u0006 \u0003רבא לכוליה חמרא\u0004 \u0005[את כל היין],\u0006 גם את מה שבחבית ממנה שאבו את היין.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב אדא בר מתנה לרבא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רבינא לרבא: במאי\u0004 \u0005[במה]\u0006 נאסר היין? \u0003בנצוק,\u0004 שזרם היין שבתוך הגישתא נאסר במגע הגוי, וחזר ואסר כל החבית. \u0003שמעת מינה\u0004 \u0005[\u0006האם יש \u0005ללמוד מכאן]\u0006 ש\u0003נצוק\u0004 הריהו \u0003חיבור?\u0004 ודחה רבא: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003דכולי חמרא אגישתא ובת גישתא גריר\u0004 \u0005[שכל היין על\u0006 ידי \u0005הקנה ובן קנה\u0006 הוא \u0005נגרר]\u0006 שכל היין נמשך לשם, ולכן הרי זה כאילו נוגע בידו בכל היין שבחבית.","\u0003אמר מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן: קנישקנין\u0004 כלי יין שיש בו כמה קנים, וכמה אנשים שותים ממנו במציצה — \u0003שרי\u0004 \u0005[מותר]\u0006 ליהודי וגוי לשתות יחד. \u0003והני מילי דקדים פסק\u0004 \u0005[ודברים אלה\u0006 אמורים \u0005שקודם ומפסיק]\u0006 \u0003ישראל\u0004 את השתיה, ואחריו מפסיק הגוי, \u0003אבל\u0004 אם \u0003קדם פסק\u0004 \u0005[קודם ומפסיק]\u0006 \u0003גוי\u0004 — \u0003לא,\u0004 שהיין חוזר מפיו לכלי, ואוסר את היין המצוי שם. מסופר, \u0003רבה בר רב הונא איקלע לבי ריש גלותא\u0004 \u0005[נזדמן לבית ראש הגולה],\u0006 \u0003שרא להו למשתא\u0004 \u0005[התיר להם לשתות]\u0006 \u0003בקנישקנין\u0004 יחד עם הגוי."],["\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003רבה בר רב הונא גופיה אישתי\u0004 \u0005[\u0006הוא \u0005עצמו שתה]\u0006 עם גוי \u0003בקנישקנין.\u0004","\u0003יין נסך אסור ואוסר בכל שהוא\u0004 כשהוא מתערב ביינות אחרים. ומפרטים: \u0003יין\u0004 נסך שנתערב \u0003ביין\u0004 של היתר \u0003ו\u0004כן \u0003מים\u0004 שנתנסכו לעבודה זרה, שנתערבו \u0003במים\u0004 של היתר — אוסרים \u0003בכל שהוא,\u0004 אבל \u0003יין\u0004 שנתערב \u0003במים ומים\u0004 שנתערבו \u0003ביין\u0004 — אוסרים \u0003בנותן טעם.\u0004","\u0003זה הכלל: מין\u0004 שנתערב \u0003במינו\u0004 — אוסר \u0003במשהו, ושלא במינו\u0004 — אוסר \u0003בנותן טעם.\u0004","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי אמר\u0004 בשם \u0003ר' יוחנן: המערה יין נסך מחבית לבור\u0004 יין, \u0003אפילו\u0004 עשה כן \u0003כל היום כולו\u0004 — \u0003ראשון ראשון\u0004 שנשפך \u0003בטל\u0004 ביין שבבור והופך לחלק מן ההיתר, וכשיורד היין שאחריו מתבטל אף הוא.","ומקשים, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003יין נסך אסור ואוסר בכל שהוא; מאי לאו דקא נפיל איסורא לגו התירא\u0004 \u0005[האם לא\u0006 מדובר כאן \u0005שנופל האיסור בתוך ההיתר]?\u0006 והוא אוסר במשהו, ואינו מתבטל! ודוחים: \u0003לא,\u0004 מדובר במשנתנו \u0003דקא נפיל התירא לגו איסורא\u0004 \u0005[שנופל ההיתר אל תוך האיסור],\u0006 ואז אנו אומרים שהאיסור אוסר במשהו את ההיתר שנפל לתוכו, למרות שבמשך הזמן מתרבה כמות ההיתר שנפלה לתוכו.","ומקשים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003יין במים\u0004 — \u0003בנותן טעם; מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003דקא נפיל חמרא דאיסורא למיא דהתירא\u0004 \u0005[שנופל יין של איסור לתוך מים של היתר]?\u0006 והרי אינו בטל, אלא הוא אוסר משעה שיהא בו בנותן טעם! ודוחים: \u0003לא, דקא נפיל חמרא דהתירא למיא דאיסורא\u0004 \u0005[\u0006מדובר \u0005שנופל יין של היתר למים של איסור]\u0006 וכל זמן שהמים משפיעים על טעמו של היין — הרי הוא אסור.","ושואלים: \u0003ומדרישא במיא דאיסורא, סיפא נמי במיא דאיסורא\u0004 \u0005[ומתוך שבראשה\u0006 של אותה הלכה מדובר \u0005במים אסורים, סופה גם כן\u0006 צריך לפרש \u0005במים האסורים],\u0006 \u0003וקתני סיפא\u0004 \u0005[ושנה בסופה]:\u0006 \u0003מים ביין\u0004 — \u0003בנותן טעם,\u0004 ואינו בטל ראשון ראשון, למרות שהוא איסור הנופל להיתר! ומשיבים, \u0003אמר לך\u0004 \u0005[יכול היה לומר לך]\u0006 \u0003רב דימי: כולה מתניתין התירא לגו איסורא\u0004 \u0005[בכל משנתנו\u0006 מדובר על \u0005היתר\u0006 שנפל \u0005לתוך איסור],\u0006 \u0003ורישא\u0004 \u0005[ובהתחלה]\u0006 מדובר \u0003דקא נפיל חמרא דהתירא למיא דאיסורא\u0004 \u0005[שנפל יין של היתר למים של איסור],\u0006 \u0003סיפא\u0004 \u0005[בסוף]\u0006 מדובר \u0003דקא נפיל מיא דהתירא לחמרא דאיסורא\u0004 \u0005[שנפלו מים של היתר ליין של איסור].\u0006","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב יצחק בר יוסף אמר\u0004 בשם \u0003ר' יוחנן: המערה יין נסך מצרצור\u0004 (פך) \u0003קטן לבור, אפילו\u0004 היה מערה אותו \u0003כל היום כולו\u0004 — \u0003ראשון ראשון בטל.\u0004 ומעירים: \u0003ודוקא צרצור קטן, דלא נפיש עמודיה\u0004 \u0005[שאין העמוד,\u0006 הקילוח \u0005שלו מרובה],\u0006 \u0003אבל חבית דנפיש עמודיה\u0004 \u0005[שמרובה הקילוח שלה]\u0006 — \u0003לא.\u0004","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין אמר\u0004 בשם \u0003ר' יוחנן: יין נסך שנפל לבור\u0004 שהיה שם יין של היתר, \u0003ונפל שם קיתון של מים\u0004 — \u0003רואין את\u0004 יין \u0003ההיתר כאילו אינו,\u0004 שאין יין הנסך אוסר אותו, \u0003והשאר\u0004 (היין האסור) ה\u0003מים רבין עליו\u0004 \u0003ומבטלין אותו.\u0004","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב שמואל בר יהודה אמר\u0004 בשם \u0003ר' יוחנן: לא שנו אלא שנפל קיתון של מים תחלה,\u0004 ואחר כך נפל לשם יין נסך, \u0003אבל לא נפל שם קיתון של מים תחלה\u0004 — אנו אומרים שמתחילה \u0003מצא מין את מינו\u0004 (יין נסך את היין שבבור) \u0003וניעור\u0004 שהיין האסור כבר מצא יין היתר שהוא מינו, ואסרו, ובמקרה כזה בוודאי אין במים כדי לבטל טעם היין כולו.","\u0003איכא דמתני לה אמתניתין\u0004 \u0005[יש ששונים\u0006 את ההלכה הזו \u0005על משנתנו],\u0006 ששנינו בה: \u0003יין ביין\u0004 — \u0003כל שהוא. אמר רב שמואל בר יהודה אמר ר' יוחנן: לא שנו אלא שלא נפל שם קיתון של מים, אבל נפל שם קיתון של מים\u0004 — \u0003רואין את\u0004 יין \u0003ההיתר כאילו אינו, והשאר מים רבין עליו ומבטלין אותו.\u0004","ושואלים: \u0003מאי איכא בין לדמתני לה אמתניתין בין לדמתני לה אדרבין\u0004 \u0005[מה\u0006 הבדל \u0005יש בין זה ששונה\u0006 את ההלכה הזו \u0005על\u0006 דברי \u0005משנתנו, ובין זה ששונה אותה על\u0006 דברי \u0005רבין]?\u0006 ומסבירים: \u0003מאן דמתני לה אמתניתין\u0004 \u0005[מי ששונה אותה על משנתנו]\u0006 \u0003לא בעי\u0004 \u0005[אינו צריך]\u0006 שיהא קיתון המים \u0003תחלה,\u0004 ובכל מקרה מבטלים המים את היין האסור, \u0003ומאן דמתני לה אדרבין\u0004 \u0005[ומי ששונה אותה על\u0006 דברי \u0005רבין]\u0006 הריהו מוסיף על דבריו, ולפיכך לשיטה זו \u0003בעי\u0004 \u0005[צריך]\u0006 שיפול קיתון המים \u0003תחלה.\u0004","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003יין נסך\u0004 \u0003שנפל לבור ונפל שם קיתון של מים,\u0004"],["\u0003אמר חזקיה:\u0004 אם \u0003הגדילו\u0004 המים והיין \u0003באיסור\u0004 שיין נסך נפל לשם באחרונה — הרי הכל \u0003אסור,\u0004 שאנו אומרים שיין הנסך אוסר את היין שהיה שם (כדין מין במינו) ואז אין שיעור במים מספיק כדי לבטלו. אבל אם \u0003הגדילו בהיתר\u0004 שהיתה שם תערובת יין נסך ומים, ובטל יין הנסך במים, ואז נפל לשם יין של היתר, אינו מצטרף לאיסור (שכבר נתבטל) אלא הכל \u0003מותר.\u0004","ואילו \u0003ר' יוחנן אמר:\u0004 אפילו \u0003הגדילו באיסור\u0004 — \u0003מותר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זירא: לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003חזקיה ור' יוחנן בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' אליעזר ורבנן קמיפלגי\u0004 \u0005[הם חולקים],\u0006","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003שאור של חולין ושל תרומה שנפלו לתוך העיסה\u0004 של חולין, \u0003לא בזה\u0004 של תרומה יש בו \u0003כדי לחמץ\u0004 את העיסה \u0003ולא בזה\u0004 של חולין יש בו \u0003כדי לחמץ, ונצטרפו\u0004 זה לזה \u0003ו\u0004ביחד \u0003חמצו\u0004 את העיסה,","\u0003ר' אליעזר אומר: אחר אחרון אני בא,\u0004 שאם נפל שאור של תרומה באחרונה — הכל אסור, ואם של חולין נפל באחרונה — מותר. \u0003וחכמים אומרים: בין שנפל איסור בתחלה ובין בסוף\u0004 — \u0003אינו אסור עד שיהא בו\u0004 באיסור לבדו \u0003כדי להחמיץ.\u0004 ולכאורה חזקיה אמר כדברי ר' אליעזר, שאם נפל האיסור באחרונה אוסר, ור' יוחנן כדברי חכמים המתירים, משום שאין ביין נסך עצמו כדי לאסור.","ותמהים: \u0003ותסברא\u0004 \u0005[\u0006וכי יכול אתה \u0005לסבור\u0006 כך\u0005]\u0006 שמדובר באותה מחלוקת? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003אביי: לא שנו\u0004 שהתיר ר' אליעזר וחכמים אם נפל של היתר בסוף, \u0003אלא\u0004 במקרה \u0003שקדם וסילק את האיסור,\u0004 שלא נשאר בעיסה שאור של תרומה, \u0003אבל\u0004 אם \u0003לא קדם וסילק את האיסור\u0004 — \u0003אסור.\u0004 ולפי הסבר זה, \u0003חזקיה דאמר כמאן\u0004 \u0005[שאומר, כמי\u0006 אומר\u0005]?\u0006 שאם לשיטת חכמים — הרי הם מתירים בכל אופן, שהרי אין ביין נסך עצמו כדי לאסור. ואם לשיטת ר' אליעזר, הרי גם אם נפל יין ההיתר באחרונה תהא התערובת אסורה, שהרי לא קדם וסילק את האיסור!","\u0003אלא, הכא\u0004 \u0005[כאן]\u0006 מחלוקת חזקיה ור' יוחנן בעניין אחר היא, בשאלה של \u0003רואין קמיפלגי\u0004 \u0005[הם חלוקים],\u0006 כשיש תערובת שיש בה ממינו של האיסור, וגם דבר שאינו מינו, האם רואים את מינו כאילו אינו ושאינו מינו מבטלו, או לא, \u0003לחזקיה לית ליה\u0004 \u0005[אין לו,\u0006 אינו סבור\u0005]\u0006 \u0003רואין,\u0004 ולכן אינו מתיר אלא במקרה שיין הנסך נתבטל תחילה במים, ושוב אינו אוסר את יין ההיתר. ואילו \u0003לר' יוחנן אית ליה\u0004 \u0005[יש לו],\u0006 ולכן הוא סבור שבכל מקרה המים מבטלים את היין האסור, ואין מתחשבים ביין ההיתר המצוי שם, שאין יין הנסך אוסרו.","ושואלים: \u0003ומי אית ליה\u0004 \u0005[והאם יש לו,\u0006 סבור\u0005]\u0006 \u0003לר'\u0004 \u0003יוחנן רואין? והא בעי מיניה\u0004 \u0005[והרי שאל אותו]\u0006 \u0003ר' אסי מר' יוחנן: שני כוסות\u0004 של יין, \u0003אחד של חולין ואחד של תרומה,\u0004 \u0003ומזגן\u0004 (מהל אותם) במים, \u0003ועירבן זה בזה,\u0004 ויש במים שבשני הכוסות כדי לבטל את יין התרומה, \u0003מהו?\u0004 האם נאמר שיין החולין, שהוא מינו של יין התרומה, נחשב כאילו אינו, והמים שיש בתערובת מבטלים את יין התרומה. או שמא אוסר יין התרומה את יין החולין, ואז אין בכח המים שבשני הכוסות כדי לבטלם? \u0003ולא פשט ליה\u0004 \u0005[פתר לו],\u0006 משמע שלא היתה לו דעה ברורה בענין \"רואין\"!","ומשיבים: \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003לא פשט ליה\u0004 \u0005[פתר לו],\u0006 \u0003לבסוף\u0004 עיין בדבר ו\u0003פשט ליה\u0004 \u0005[ופתר לו]\u0006 שרואים את מינו כאילו אינו. ומנין שכן הוא, כי \u0003אתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 \u0003אמר ר' אמי אמר ר' יוחנן: ואמרי לה\u0004 \u0005[ויש אומרים אותה\u0006 בנוסח\u0005]\u0006 \u0003אמר ר' אסי אמר ר' יוחנן: שני כוסות, אחד של חולין ואחד של תרומה, ומזגן ועירבן זה בזה\u0004 — \u0003רואין את\u0004 יין \u0003ההיתר כאילו אינו, והשאר\u0004 היין של תרומה, \u0003מים רבין עליו ומבטלין אותו.\u0004 הרי שזו דעתו הסופית של ר' יוחנן.","שנינו במשנה, \u0003זה הכלל: מין במינו\u0004 — \u0003במשהו, שלא במינו\u0004 — \u0003בנותן טעם.\u0004 ומביאים מחלוקת אמוראים בענין זה.","\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 כלל זה: \u0003כל איסורין שבתורה,\u0004 אם נתערבו \u0003במינן\u0004 — אוסרים \u0003במשהו,\u0004 נתערבו \u0003שלא במינן\u0004 — \u0003בנותן טעם.\u0004","ולשיטה זו, \u0003\"זה הכלל\"\u0004 שנאמר במשנה, \u0003לאתויי מאי\u0004 \u0005[מה\u0006 בא \u0005להביא\u0006 להוסיף\u0005]?\u0006 \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003כל איסורין שבתורה,\u0004 לומר שדין זה לא נאמר דווקא ביין נסך, אלא בכל האיסורים.","ואילו \u0003ר' יוחנן וריש לקיש דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 כלל זה: \u0003כל איסורין שבתורה, בין\u0004 שנתערבו \u0003במינן בין שלא במינן\u0004 — אוסרים \u0003בנותן טעם, חוץ מטבל ויין נסך\u0004 שאוסרים \u0003במינן במשהו, ושלא במינן\u0004 — \u0003בנותן טעם. ו\u0004לשיטה זו, \u0003\"זה הכלל\"\u0004 נאמר במשנה \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003טבל,\u0004 שלא נזכר במשנתנו.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רב ושמואל,\u0004 ומצד אחר: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003ר' יוחנן וריש לקיש.\u0004","ומפרטים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רב ושמואל: כל איסורין שבתורה, במינן\u0004 — \u0003במשהו, שלא במינן\u0004 — \u0003בנותן טעם.\u0004","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003ר' יוחנן וריש לקיש: כל איסורין שבתורה, בין במינן בין שלא במינן\u0004 — \u0003בנותן טעם, חוץ מטבל ויין נסך,\u0004 ש\u0003במינן\u0004 אוסרים \u0003במשהו, שלא במינן\u0004 — \u0003בנותן טעם.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003יין נסך\u0004 אוסר כל כך, \u0003משום חומרא\u0004 \u0005[החומרה]\u0006 שיש ב\u0003עבודה זרה,\u0004 שהחמירו בה ביותר, \u0003אלא טבל מאי טעמא\u0004 \u0005[מה הטעם]\u0006 אוסר אפילו במשהו?","ומשיבים: \u0003כהיתירו כך איסורו,\u0004 ש\u0003אמר שמואל: חטה אחת\u0004 שעושים תרומה \u0003פוטרת\u0004 מדין תורה \u0003את\u0004 כל \u0003הכרי\u0004 מחובת תרומה, וכיון שחיטה אחת בלבד פוטרת, אף חיטה אחת אוסרת הכל. \u0003ותניא נמי הכי\u0004 \u0005[ושנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003במה\u0004 באיזה מקרה \u0003אמרו: טבל אוסר בכל שהוא?\u0004 דווקא \u0003במינו,\u0004 אבל \u0003שלא במינו\u0004 — אוסר \u0003בנותן טעם.\u0004"]]};
